#!/usr/bin/env node
import { McpServer } from "@modelcontextprotocol/server";
import { StdioServerTransport } from "@modelcontextprotocol/server/stdio";
import { z } from "zod";
import { isStale } from "../isStale.js";
import { quoteFromFeed } from "../quote.js";
import { checkPrice } from "../check.js";

// Types for MCP — JSON cannot carry bigint, so we use string for answer/updatedAt
const server = new McpServer({
  name: "stale",
  version: "0.1.0",
});

// stale_isStale — pure, no RPC
server.registerTool(
  "stale_isStale",
  {
    description:
      "Check if a Chainlink price is stale. Pure, no RPC. Returns ALLOW/BLOCK with age and reason. Fail closed on missing/zero/negative/unparseable/future.",
    inputSchema: z.object({
      updatedAt: z
        .string()
        .describe("updatedAt timestamp as string (bigint seconds, e.g. '1724520000' or '0x...')"),
      nowSeconds: z
        .number()
        .int()
        .describe("Current time in seconds (e.g. Math.floor(Date.now()/1000))"),
      maxAgeSeconds: z
        .number()
        .int()
        .min(0)
        .describe("Max allowed age in seconds (policy, no default)"),
    }),
  },
  async ({
    updatedAt,
    nowSeconds,
    maxAgeSeconds,
  }: {
    updatedAt: string;
    nowSeconds: number;
    maxAgeSeconds: number;
  }) => {
    const result = isStale({ updatedAt, nowSeconds, maxAgeSeconds });
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
    };
  },
);

// stale_quote — price math, no RPC
server.registerTool(
  "stale_quote",
  {
    description:
      "Price math from Data Feed answer + decimals. No RPC. Returns priceUsd and quoteUsd. Fail closed on 0n/bad decimals/NaN.",
    inputSchema: z.object({
      answer: z.string().describe("answer as string bigint, e.g. '245377000000'"),
      decimals: z
        .number()
        .int()
        .min(0)
        .max(36)
        .describe("Feed decimals, from decimals() on-chain (never hardcoded 8)"),
      amountEth: z
        .number()
        .min(0)
        .nullable()
        .optional()
        .describe("Human ETH amount for quote, e.g. 0.5, or null"),
    }),
  },
  async ({
    answer,
    decimals,
    amountEth,
  }: {
    answer: string;
    decimals: number;
    amountEth?: number | null;
  }) => {
    try {
      const result = quoteFromFeed({
        answer: BigInt(answer),
        decimals,
        amountEth: amountEth ?? null,
      });
      return {
        content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      };
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      return {
        content: [{ type: "text", text: `BLOCK — quote failed: ${msg}` }],
        isError: true,
      };
    }
  },
);

// stale_check — full check via viem, no wallet, no tx, fail closed
server.registerTool(
  "stale_check",
  {
    description:
      "Full guardrail: viem latestRoundData + decimals → isStale → quote. No wallet, no tx, fail closed. Returns same JSON as CLI --json with allowExecute. Default feed is ETH/USD mainnet; an optional feed must be allowlisted: ETH/USD 0x5f4eC3Df9cbd43714FE2740f5E3616155c5b8419 or BTC/USD 0xF4030086522a5bEEa4988F8cA5B36dbC97BeE88c on Ethereum mainnet. Unknown feed → BLOCK.",
    inputSchema: z.object({
      rpc: z.string().describe("Ethereum RPC URL (e.g. https://ethereum-rpc.publicnode.com)"),
      feed: z
        .string()
        .describe("Data Feed proxy address, e.g. 0x5f4eC3Df9cbd43714FE2740f5E3616155c5b8419"),
      maxAgeSeconds: z
        .number()
        .int()
        .min(0)
        .describe("Max allowed age in seconds (policy, no default)"),
      amountEth: z
        .number()
        .min(0)
        .nullable()
        .optional()
        .describe("Human ETH amount for quote, e.g. 0.5"),
      nowSeconds: z.number().int().optional().describe("Override now for testing, else Date.now()"),
    }),
  },
  async ({
    rpc,
    feed,
    maxAgeSeconds,
    amountEth,
    nowSeconds,
  }: {
    rpc: string;
    feed: string;
    maxAgeSeconds: number;
    amountEth?: number | null;
    nowSeconds?: number;
  }) => {
    const result = await checkPrice({
      rpc,
      feed,
      maxAgeSeconds,
      amountEth: amountEth ?? null,
      nowSeconds,
    });
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
    };
  },
);

async function main(): Promise<void> {
  const transport = new StdioServerTransport();
  await server.connect(transport);
}

main().catch((err: unknown) => {
  console.error(err instanceof Error ? err.message : String(err));
  process.exit(1);
});

/**
 * A single-exchange, per-request HTTP server transport for modern-era
 * (protocol revision 2026-07-28) serving.
 *
 * One transport instance serves exactly one already-classified inbound
 * JSON-RPC message and produces exactly one HTTP `Response`:
 *
 * - a `202` with no body for notifications,
 * - a single JSON body for requests whose handler produces no streamed
 *   output, or
 * - a lazily-opened SSE stream when the handler emits related messages
 *   (notifications or server-to-client requests) before its result — the
 *   stream carries those messages and finally the terminal result, then
 *   closes.
 *
 * The transport is constructed already-classified: the entry parses and
 * classifies the request body exactly once and hands the classification in via
 * the constructor; the transport attaches it (together with the original
 * request and any caller-provided auth info) to every message it delivers, and
 * the protocol layer validates it against the serving instance's negotiated
 * era. `authInfo` is strictly pass-through — it is never derived from the
 * inbound request's headers here.
 *
 * Deliberately NOT carried over from the session-oriented streamable HTTP
 * transport: session ids and session headers, resumability (event ids,
 * priming events, `Last-Event-ID` replay, retry hints), the standalone GET
 * stream, and request-header validation (which belongs to middleware). The
 * exchange is single-use; serving another request requires a new transport
 * (and, in the per-request serving model, a fresh server instance).
 *
 * Consumers wiring this transport into a custom entry (instead of
 * `createMcpHandler`) inherit the spec's per-error HTTP mandate with it: a
 * terminal `MissingRequiredClientCapabilityError` (-32021) MUST answer 400,
 * which this transport applies whenever the response is still uncommitted.
 * A custom entry must also reject POSTs whose Content-Type media type is not
 * `application/json` (415) before parsing the body — use `isJsonContentType`
 * from the package root; this transport never sees the HTTP headers, so it
 * cannot perform that validation itself.
 */
import type {
    AuthInfo,
    JSONRPCMessage,
    JSONRPCNotification,
    JSONRPCRequest,
    MessageClassification,
    MessageExtraInfo,
    RequestId,
    Transport,
    TransportSendOptions
} from '@modelcontextprotocol/core-internal';
import {
    isJSONRPCErrorResponse,
    isJSONRPCRequest,
    isJSONRPCResultResponse,
    LADDER_ERROR_HTTP_STATUS,
    ProtocolErrorCode,
    SdkError,
    SdkErrorCode
} from '@modelcontextprotocol/core-internal';

import { armSseKeepAlive, DEFAULT_SSE_KEEP_ALIVE_MS } from './sseKeepAlive';

/**
 * How the transport shapes its HTTP response for a request:
 *
 * - `auto` (default): answer with a single JSON body unless the handler emits
 *   a related message before its result, in which case the response upgrades
 *   to an SSE stream.
 * - `sse`: always answer handler output over an SSE stream. The stream opens
 *   once the request has passed the pre-dispatch validation gates, so ladder
 *   rejections keep their mapped HTTP status instead of being framed onto a
 *   200 stream.
 * - `json`: never stream; related messages other than the terminal response
 *   are dropped.
 */
export type PerRequestResponseMode = 'auto' | 'sse' | 'json';

/** Constructor options for {@linkcode PerRequestHTTPServerTransport}. */
export interface PerRequestHTTPServerTransportOptions {
    /** The edge classification of the message this transport will serve. */
    classification: MessageClassification;
    /** Response shaping for the exchange; defaults to `auto`. */
    responseMode?: PerRequestResponseMode;
    /** SSE keep-alive interval in milliseconds; defaults to `15000`, `0` disables. */
    keepAliveMs?: number;
}

/** Per-exchange context handed to {@linkcode PerRequestHTTPServerTransport.handleMessage}. */
export interface PerRequestMessageExtra {
    /**
     * The original HTTP request. Used for handler context and, when the
     * runtime provides an abort signal on it, to cancel the exchange when the
     * client disconnects.
     */
    request?: globalThis.Request;
    /**
     * Validated authentication information supplied by the caller. Strictly
     * pass-through: the transport never populates this from request headers.
     */
    authInfo?: AuthInfo;
}

interface DeferredResponse {
    promise: Promise<Response>;
    resolve: (response: Response) => void;
    reject: (error: Error) => void;
    settled: boolean;
}

interface SseSink {
    controller: ReadableStreamDefaultController<Uint8Array>;
    encoder: InstanceType<typeof TextEncoder>;
    closed: boolean;
    keepAliveTimer?: ReturnType<typeof setInterval>;
}

/**
 * The per-request micro-transport: a real, connected `Transport` whose whole
 * lifetime is one HTTP exchange. See the module documentation for the
 * response shapes it produces.
 */
export class PerRequestHTTPServerTransport implements Transport {
    onclose?: () => void;
    onerror?: (error: Error) => void;
    onmessage?: <T extends JSONRPCMessage>(message: T, extra?: MessageExtraInfo) => void;

    private readonly _classification: MessageClassification;
    private readonly _responseMode: PerRequestResponseMode;

    private _started = false;
    private _used = false;
    private _closed = false;
    private _terminalDelivered = false;
    /**
     * `true` only while the inbound message is being delivered synchronously
     * to the connected protocol layer. The pre-handler gates (the era
     * registry gate, the edge→instance handoff check, the missing-handler
     * rejection) answer inside this window; request handlers always run
     * after it (the protocol layer defers them to a microtask). An error
     * sent inside the window is therefore ladder-originated, and an error
     * sent after it is handler-produced.
     */
    private _dispatchWindowOpen = false;
    private _requestId?: RequestId;
    private _deferredResponse?: DeferredResponse;
    private _sse?: SseSink;
    private _abortCleanup?: () => void;
    private readonly _keepAliveMs: number;

    constructor(options: PerRequestHTTPServerTransportOptions) {
        this._classification = options.classification;
        this._responseMode = options.responseMode ?? 'auto';
        this._keepAliveMs = options.keepAliveMs ?? DEFAULT_SSE_KEEP_ALIVE_MS;
    }

    async start(): Promise<void> {
        if (this._started) {
            throw new Error('PerRequestHTTPServerTransport is already started');
        }
        this._started = true;
    }

    /**
     * Serves the single exchange: delivers the classified message to the
     * connected server instance and resolves with the HTTP response.
     *
     * Throws when called a second time (the transport is strictly
     * single-use), or before a server has been connected to the transport.
     * The returned promise rejects with a connection-closed error when the
     * transport is closed before a response was produced (for example because
     * the client disconnected).
     */
    async handleMessage(message: JSONRPCRequest | JSONRPCNotification, extra?: PerRequestMessageExtra): Promise<Response> {
        if (this._used) {
            throw new Error('PerRequestHTTPServerTransport serves exactly one exchange; construct a new transport per request');
        }
        if (!this._started || this.onmessage === undefined) {
            throw new Error('PerRequestHTTPServerTransport is not connected: connect a server to this transport before handling a message');
        }
        if (this._closed) {
            throw new Error('PerRequestHTTPServerTransport is closed');
        }
        this._used = true;

        const signal = extra?.request?.signal;
        if (signal?.aborted) {
            await this.close();
            throw new SdkError(SdkErrorCode.ConnectionClosed, 'The request was aborted before it could be handled');
        }

        // authInfo is strictly pass-through from the caller; it is never
        // derived from the inbound request's headers.
        const messageExtra: MessageExtraInfo = {
            classification: this._classification,
            ...(extra?.request !== undefined && { request: extra.request }),
            ...(extra?.authInfo !== undefined && { authInfo: extra.authInfo })
        };

        if (isJSONRPCRequest(message)) {
            this._requestId = message.id;

            let resolve!: (response: Response) => void;
            let reject!: (error: Error) => void;
            const promise = new Promise<Response>((promiseResolve, promiseReject) => {
                resolve = promiseResolve;
                reject = promiseReject;
            });
            this._deferredResponse = { promise, resolve, reject, settled: false };

            if (signal !== undefined) {
                const onAbort = () => void this.close();
                signal.addEventListener('abort', onAbort, { once: true });
                this._abortCleanup = () => signal.removeEventListener('abort', onAbort);
            }

            this._dispatchWindowOpen = true;
            try {
                this.onmessage(message, messageExtra);
            } finally {
                this._dispatchWindowOpen = false;
            }

            if (this._responseMode === 'sse' && !this._closed && !this._deferredResponse.settled) {
                // Forced-SSE exchanges open their stream as soon as the
                // request has passed the pre-dispatch gates: a ladder
                // rejection settles inside the dispatch window with its
                // mapped HTTP status, while handler output — including
                // comment frames written before the first message — streams
                // as before.
                this.upgradeToSse();
            }
            return promise;
        }

        // Notifications never get a JSON-RPC response: deliver the message and
        // acknowledge the POST with 202 and no body.
        this.onmessage(message, messageExtra);
        return new Response(null, { status: 202 });
    }

    async send(message: JSONRPCMessage, options?: TransportSendOptions): Promise<void> {
        if (this._closed) {
            // The exchange is over; late writes are dropped.
            return;
        }

        const isResponse = isJSONRPCResultResponse(message) || isJSONRPCErrorResponse(message);
        const relatedId = isResponse ? (message as { id: RequestId }).id : options?.relatedRequestId;

        if (this._requestId === undefined || relatedId === undefined || relatedId !== this._requestId) {
            if (isResponse) {
                this.onerror?.(new Error(`Received a response for an unknown request id: ${String((message as { id?: unknown }).id)}`));
            }
            // Messages unrelated to the single in-flight request have nowhere
            // to go on a per-request exchange (there is no session-wide
            // stream); they are dropped.
            return;
        }

        if (isResponse) {
            if (this._terminalDelivered) {
                return;
            }
            this._terminalDelivered = true;

            // The HTTP status is keyed on the error's origin, not on its bare
            // code: only errors produced inside the dispatch window — the
            // validation ladder, the era registry gate and handoff check, a
            // missing handler — are answered with the mapped HTTP status from
            // the ladder table. Handler-produced errors, whatever their code,
            // stay in-band on HTTP 200 — except
            // MissingRequiredClientCapability (-32021), whose 400 the spec
            // mandates per-error with no origin condition and whose only
            // SDK-produced post-window source (the input_required capability
            // gate) cannot fire any earlier — a handler-minted -32021 gets
            // the same 400; a handler RELAYING a downstream peer's
            // -32020/-32022 is not that peer's spec error and stays in-band.
            // Must agree with httpStatusForErrorCode (core-internal), which
            // is deliberately NOT called here: its `?? 400` ladder fallback
            // would wrongly map window codes outside the table.
            // The mapping applies only while no response has been committed:
            // once the stream is open — the handler streamed first, or the
            // exchange is forced-`sse` (which settles its 200 at dispatch
            // end) — the status is on the wire and the error rides the
            // stream. Pre-dispatch ladder rejections always precede the
            // forced-`sse` upgrade, so they keep their mapped status in every
            // response mode.
            const errorCode = isJSONRPCErrorResponse(message) ? message.error.code : undefined;
            const ladderStatus =
                errorCode !== undefined && (this._dispatchWindowOpen || errorCode === ProtocolErrorCode.MissingRequiredClientCapability)
                    ? LADDER_ERROR_HTTP_STATUS[errorCode]
                    : undefined;
            if (ladderStatus !== undefined && this._sse === undefined) {
                this.settleResponse(Response.json(message, { status: ladderStatus, headers: { 'Content-Type': 'application/json' } }));
                queueMicrotask(() => void this.close());
                return;
            }

            if (this._sse !== undefined || this._responseMode === 'sse') {
                // Finalize the stream: serialize the terminal result onto it
                // after everything already enqueued, then close.
                if (this._sse === undefined) {
                    this.upgradeToSse();
                }
                this.writeMessageFrame(message);
                this.finalizeStream();
                return;
            }

            // Single JSON body.
            this.settleResponse(Response.json(message, { status: 200, headers: { 'Content-Type': 'application/json' } }));
            queueMicrotask(() => void this.close());
            return;
        }

        // A message related to the in-flight request that is not its terminal
        // response: a mid-call notification or a server-to-client request
        // emitted by the handler.
        if (this._responseMode === 'json') {
            // JSON responses cannot carry mid-call messages; they are dropped.
            return;
        }
        if (this._sse === undefined) {
            this.upgradeToSse();
        }
        this.writeMessageFrame(message);
    }

    /**
     * Writes an SSE comment frame (a keep-alive heartbeat). Dropped when the
     * exchange is not currently streaming.
     */
    writeCommentFrame(comment: string): void {
        if (this._closed || this._sse === undefined || this._sse.closed) {
            return;
        }
        const frame = comment
            .split('\n')
            .map(line => `: ${line}`)
            .join('\n');
        this.writeFrame(`${frame}\n\n`);
    }

    async close(): Promise<void> {
        if (this._closed) {
            return;
        }
        this._closed = true;

        this._abortCleanup?.();
        this._abortCleanup = undefined;

        if (this._sse?.keepAliveTimer !== undefined) {
            clearInterval(this._sse.keepAliveTimer);
        }
        if (this._sse !== undefined && !this._sse.closed) {
            this._sse.closed = true;
            try {
                this._sse.controller.close();
            } catch {
                // The stream was already closed or cancelled by the consumer.
            }
        }

        if (this._deferredResponse !== undefined && !this._deferredResponse.settled) {
            this._deferredResponse.settled = true;
            this._deferredResponse.reject(new SdkError(SdkErrorCode.ConnectionClosed, 'Connection closed before a response was produced'));
        }

        this.onclose?.();
    }

    private settleResponse(response: Response): void {
        if (this._deferredResponse === undefined || this._deferredResponse.settled) {
            return;
        }
        this._deferredResponse.settled = true;
        this._deferredResponse.resolve(response);
    }

    private upgradeToSse(): void {
        let controller!: ReadableStreamDefaultController<Uint8Array>;
        const readable = new ReadableStream<Uint8Array>({
            start: streamController => {
                controller = streamController;
            },
            cancel: () => {
                // The client went away mid-stream: tear the exchange down,
                // which aborts the in-flight handler through the connected
                // server's close chain.
                void this.close();
            }
        });
        this._sse = { controller, encoder: new TextEncoder(), closed: false };
        this._sse.keepAliveTimer = armSseKeepAlive(this._keepAliveMs, () => this.writeCommentFrame('keepalive'));

        this.settleResponse(
            new Response(readable, {
                status: 200,
                headers: {
                    'Content-Type': 'text/event-stream',
                    'Cache-Control': 'no-cache, no-transform',
                    Connection: 'keep-alive',
                    // Disable proxy buffering so streamed messages are
                    // delivered as they are written.
                    'X-Accel-Buffering': 'no'
                }
            })
        );
    }

    private finalizeStream(): void {
        if (this._sse?.keepAliveTimer !== undefined) {
            clearInterval(this._sse.keepAliveTimer);
        }
        if (this._sse !== undefined && !this._sse.closed) {
            this._sse.closed = true;
            try {
                this._sse.controller.close();
            } catch {
                // The stream was already cancelled by the consumer.
            }
        }
        queueMicrotask(() => void this.close());
    }

    private writeMessageFrame(message: JSONRPCMessage): void {
        this.writeFrame(`event: message\ndata: ${JSON.stringify(message)}\n\n`);
    }

    private writeFrame(frame: string): void {
        if (this._sse === undefined || this._sse.closed) {
            return;
        }
        try {
            this._sse.controller.enqueue(this._sse.encoder.encode(frame));
        } catch (error) {
            this.onerror?.(new Error(`Failed to write to the response stream: ${error}`));
        }
    }
}
/**
 * The internal per-request invoke seam for modern-era HTTP serving.
 *
 * One classified inbound message is served by composing existing pieces, with
 * no changes to the protocol dispatch layer:
 *
 *   server instance (from the consumer's factory)
 *     → `connect(per-request transport)`
 *     → inject the classified message through the transport's message callback
 *     → capture the value (a single JSON body or an SSE stream) via the
 *       transport's send path.
 *
 * The seam is value-returning and independently testable: it resolves with the
 * HTTP `Response` for the exchange. Marking factory instances as modern-era
 * (and installing modern-only handlers) is the calling entry's responsibility
 * and happens before this seam runs; the seam itself never writes era state.
 */
import type { AuthInfo, JSONRPCNotification, JSONRPCRequest, MessageClassification } from '@modelcontextprotocol/core-internal';

import type { McpServer } from './mcp';
import type { PerRequestResponseMode } from './perRequestTransport';
import { PerRequestHTTPServerTransport } from './perRequestTransport';
import type { Server } from './server';

/** Per-exchange context for {@linkcode invoke}. */
export interface InvokeContext {
    /** The edge classification of the message (computed once, at the entry boundary). */
    classification: MessageClassification;
    /** The original HTTP request, when serving HTTP traffic. */
    request?: globalThis.Request;
    /**
     * Validated authentication information supplied by the caller. Strictly
     * pass-through — never derived from request headers by this seam.
     */
    authInfo?: AuthInfo;
    /** Response shaping for the exchange; defaults to `auto` (lazy SSE upgrade). */
    responseMode?: PerRequestResponseMode;
    /** SSE keep-alive interval for the exchange. */
    keepAliveMs?: number;
}

/**
 * Serves one classified inbound message on the given server instance and
 * returns the HTTP response for the exchange.
 *
 * The instance is connected to a fresh single-exchange transport, the message
 * is injected through the normal transport message path, and whatever the
 * dispatch layer produces (the handler result, a protocol-level rejection, or
 * streamed related messages followed by the result) is captured as the
 * returned `Response`. For request exchanges, teardown rides the transport's
 * close chain once the terminal response has been delivered; notification
 * exchanges resolve with the 202 response immediately and do NOT run the
 * close chain — the transport stays connected until the caller closes it or
 * drops the per-request instance, which is the caller's choice either way.
 */
export async function invoke(
    server: Server | McpServer,
    message: JSONRPCRequest | JSONRPCNotification,
    ctx: InvokeContext
): Promise<Response> {
    const transport = new PerRequestHTTPServerTransport({
        classification: ctx.classification,
        ...(ctx.responseMode !== undefined && { responseMode: ctx.responseMode }),
        ...(ctx.keepAliveMs !== undefined && { keepAliveMs: ctx.keepAliveMs })
    });
    await server.connect(transport);
    return transport.handleMessage(message, {
        ...(ctx.request !== undefined && { request: ctx.request }),
        ...(ctx.authInfo !== undefined && { authInfo: ctx.authInfo })
    });
}
/**
 * Web Standards Streamable HTTP Server Transport
 *
 * This is the core transport implementation using Web Standard APIs (`Request`, `Response`, `ReadableStream`).
 * It can run on any runtime that supports Web Standards: Node.js 18+, Cloudflare Workers, Deno, Bun, etc.
 *
 * For Node.js Express/HTTP compatibility, use {@linkcode @modelcontextprotocol/node!NodeStreamableHTTPServerTransport | NodeStreamableHTTPServerTransport} which wraps this transport.
 */

import type { AuthInfo, JSONRPCMessage, MessageExtraInfo, RequestId, Transport } from '@modelcontextprotocol/core-internal';
import {
    DEFAULT_NEGOTIATED_PROTOCOL_VERSION,
    isInitializeRequest,
    isJsonContentType,
    isJSONRPCErrorResponse,
    isJSONRPCRequest,
    isJSONRPCResultResponse,
    JSONRPCMessageSchema,
    SUPPORTED_PROTOCOL_VERSIONS
} from '@modelcontextprotocol/core-internal';

import { armSseKeepAlive, DEFAULT_SSE_KEEP_ALIVE_MS } from './sseKeepAlive';

export type StreamId = string;
export type EventId = string;

/**
 * Interface for resumability support via event storage
 */
export interface EventStore {
    /**
     * Stores an event for later retrieval
     * @param streamId ID of the stream the event belongs to
     * @param message The JSON-RPC message to store
     * @returns The generated event ID for the stored event
     */
    storeEvent(streamId: StreamId, message: JSONRPCMessage): Promise<EventId>;

    /**
     * Get the stream ID associated with a given event ID.
     * @param eventId The event ID to look up
     * @returns The stream ID, or `undefined` if not found
     *
     * Optional: If not provided, the SDK will use the `streamId` returned by
     * {@linkcode replayEventsAfter} for stream mapping.
     */
    getStreamIdForEventId?(eventId: EventId): Promise<StreamId | undefined>;

    replayEventsAfter(
        lastEventId: EventId,
        {
            send
        }: {
            send: (eventId: EventId, message: JSONRPCMessage) => Promise<void>;
        }
    ): Promise<StreamId>;
}

/**
 * Internal stream mapping for managing SSE connections
 */
interface StreamMapping {
    /** Stream controller for pushing SSE data - only used with `ReadableStream` approach */
    controller?: ReadableStreamDefaultController<Uint8Array>;
    /** Text encoder for SSE formatting */
    encoder?: InstanceType<typeof TextEncoder>;
    /** Promise resolver for JSON response mode */
    resolveJson?: (response: Response) => void;
    /**
     * Event ids already written to this stream by `replayEventsAfter` — lets
     * `send()` skip a duplicate write when the resumed stream registered
     * during the `storeEvent()` await and replay already delivered the event.
     */
    replayedEventIds?: Set<string>;
    /** Cleanup function to close stream and remove mapping */
    cleanup: () => void;
}

/**
 * Configuration options for {@linkcode WebStandardStreamableHTTPServerTransport}
 */
export interface WebStandardStreamableHTTPServerTransportOptions {
    /**
     * Function that generates a session ID for the transport.
     * The session ID SHOULD be globally unique and cryptographically secure (e.g., a securely generated UUID, a JWT, or a cryptographic hash)
     *
     * If not provided, session management is disabled (stateless mode).
     */
    sessionIdGenerator?: (() => string) | undefined;

    /**
     * A callback for session initialization events
     * This is called when the server initializes a new session.
     * Useful in cases when you need to register multiple mcp sessions
     * and need to keep track of them.
     * @param sessionId The generated session ID
     */
    onsessioninitialized?: ((sessionId: string) => void | Promise<void>) | undefined;

    /**
     * A callback for session close events
     * This is called when the server closes a session due to a `DELETE` request.
     * Useful in cases when you need to clean up resources associated with the session.
     * Note that this is different from the transport closing, if you are handling
     * HTTP requests from multiple nodes you might want to close each
     * {@linkcode WebStandardStreamableHTTPServerTransport} after a request is completed while still keeping the
     * session open/running.
     * @param sessionId The session ID that was closed
     */
    onsessionclosed?: ((sessionId: string) => void | Promise<void>) | undefined;

    /**
     * If `true`, the server will return JSON responses instead of starting an SSE stream.
     * This can be useful for simple request/response scenarios without streaming.
     * Default is `false` (SSE streams are preferred).
     */
    enableJsonResponse?: boolean;

    /**
     * Event store for resumability support
     * If provided, resumability will be enabled, allowing clients to reconnect and resume messages
     */
    eventStore?: EventStore;

    /**
     * List of allowed `Host` header values for DNS rebinding protection.
     * If not specified, host validation is disabled.
     * @deprecated Use external middleware for host validation instead.
     */
    allowedHosts?: string[];

    /**
     * List of allowed `Origin` header values for DNS rebinding protection.
     * If not specified, origin validation is disabled.
     * @deprecated Use external middleware for origin validation instead.
     */
    allowedOrigins?: string[];

    /**
     * Enable DNS rebinding protection (requires `allowedHosts` and/or `allowedOrigins` to be configured).
     * Default is `false` for backwards compatibility.
     * @deprecated Use external middleware for DNS rebinding protection instead.
     */
    enableDnsRebindingProtection?: boolean;

    /**
     * Retry interval in milliseconds to suggest to clients in SSE `retry` field.
     * When set, the server will send a `retry` field in SSE priming events to control
     * client reconnection timing for polling behavior.
     */
    retryInterval?: number;

    /**
     * Interval in milliseconds between SSE keep-alive comment frames.
     * Defaults to `15000`; set to `0` to disable.
     */
    keepAliveMs?: number;

    /**
     * List of protocol versions that this transport will accept.
     * Used to validate the `mcp-protocol-version` header in incoming requests.
     *
     * Note: When using {@linkcode server/server.Server.connect | Server.connect()}, the server automatically passes its
     * `supportedProtocolVersions` to the transport, so you typically don't need
     * to set this option directly.
     *
     * @default {@linkcode SUPPORTED_PROTOCOL_VERSIONS}
     */
    supportedProtocolVersions?: string[];
}

/**
 * Options for handling a request
 */
export interface HandleRequestOptions {
    /**
     * Pre-parsed request body. If provided, the transport will use this instead of parsing `req.json()`.
     * Useful when using body-parser middleware that has already parsed the body.
     */
    parsedBody?: unknown;

    /**
     * Authentication info from middleware. If provided, will be passed to message handlers.
     */
    authInfo?: AuthInfo;
}

/**
 * Server transport for Web Standards Streamable HTTP: this implements the MCP Streamable HTTP transport specification
 * using Web Standard APIs (`Request`, `Response`, `ReadableStream`).
 *
 * This transport works on any runtime that supports Web Standards: Node.js 18+, Cloudflare Workers, Deno, Bun, etc.
 *
 * In stateful mode:
 * - Session ID is generated and included in response headers
 * - Session ID is always included in initialization responses
 * - Requests with invalid session IDs are rejected with `404 Not Found`
 * - Non-initialization requests without a session ID are rejected with `400 Bad Request`
 * - State is maintained in-memory (connections, message history)
 *
 * In stateless mode:
 * - No Session ID is included in any responses
 * - No session validation is performed
 *
 * @example Stateful setup
 * ```ts source="./streamableHttp.examples.ts#WebStandardStreamableHTTPServerTransport_stateful"
 * const server = new McpServer({ name: 'my-server', version: '1.0.0' });
 *
 * const transport = new WebStandardStreamableHTTPServerTransport({
 *     sessionIdGenerator: () => crypto.randomUUID()
 * });
 *
 * await server.connect(transport);
 * ```
 *
 * @example Stateless setup
 * ```ts source="./streamableHttp.examples.ts#WebStandardStreamableHTTPServerTransport_stateless"
 * const transport = new WebStandardStreamableHTTPServerTransport({
 *     sessionIdGenerator: undefined
 * });
 * ```
 *
 * @example Hono.js
 * ```ts source="./streamableHttp.examples.ts#WebStandardStreamableHTTPServerTransport_hono"
 * app.all('/mcp', async c => {
 *     return transport.handleRequest(c.req.raw);
 * });
 * ```
 *
 * @example Cloudflare Workers
 * ```ts source="./streamableHttp.examples.ts#WebStandardStreamableHTTPServerTransport_workers"
 * const worker = {
 *     async fetch(request: Request): Promise<Response> {
 *         return transport.handleRequest(request);
 *     }
 * };
 * ```
 */
export class WebStandardStreamableHTTPServerTransport implements Transport {
    // when sessionId is not set (undefined), it means the transport is in stateless mode
    private sessionIdGenerator: (() => string) | undefined;
    private _started: boolean = false;
    private _closed: boolean = false;
    private _streamMapping: Map<string, StreamMapping> = new Map();
    private _requestToStreamMapping: Map<RequestId, string> = new Map();
    private _requestResponseMap: Map<RequestId, JSONRPCMessage> = new Map();
    private _initialized: boolean = false;
    private _enableJsonResponse: boolean = false;
    private _standaloneSseStreamId: string = '_GET_stream';
    private _eventStore?: EventStore;
    private _onsessioninitialized?: ((sessionId: string) => void | Promise<void>) | undefined;
    private _onsessionclosed?: ((sessionId: string) => void | Promise<void>) | undefined;
    private _allowedHosts?: string[];
    private _allowedOrigins?: string[];
    private _enableDnsRebindingProtection: boolean;
    private _retryInterval?: number;
    private _supportedProtocolVersions: string[];
    private _keepAliveMs: number;

    sessionId?: string;
    onclose?: () => void;
    onerror?: (error: Error) => void;
    onmessage?: (message: JSONRPCMessage, extra?: MessageExtraInfo) => void;

    constructor(options: WebStandardStreamableHTTPServerTransportOptions = {}) {
        this.sessionIdGenerator = options.sessionIdGenerator;
        this._enableJsonResponse = options.enableJsonResponse ?? false;
        this._eventStore = options.eventStore;
        this._onsessioninitialized = options.onsessioninitialized;
        this._onsessionclosed = options.onsessionclosed;
        this._allowedHosts = options.allowedHosts;
        this._allowedOrigins = options.allowedOrigins;
        this._enableDnsRebindingProtection = options.enableDnsRebindingProtection ?? false;
        this._retryInterval = options.retryInterval;
        this._supportedProtocolVersions = options.supportedProtocolVersions ?? SUPPORTED_PROTOCOL_VERSIONS;
        this._keepAliveMs = options.keepAliveMs ?? DEFAULT_SSE_KEEP_ALIVE_MS;
    }

    private startKeepAlive(
        controller: ReadableStreamDefaultController<Uint8Array>,
        encoder: InstanceType<typeof TextEncoder>
    ): ReturnType<typeof setInterval> | undefined {
        if (this._closed) return undefined;

        const timer = armSseKeepAlive(this._keepAliveMs, () => {
            try {
                controller.enqueue(encoder.encode(': keepalive\n\n'));
            } catch {
                if (timer !== undefined) clearInterval(timer);
            }
        });
        return timer;
    }

    /**
     * Starts the transport. This is required by the {@linkcode Transport} interface but is a no-op
     * for the Streamable HTTP transport as connections are managed per-request.
     */
    async start(): Promise<void> {
        if (this._started) {
            throw new Error('Transport already started');
        }
        this._started = true;
    }

    /**
     * Sets the supported protocol versions for header validation.
     * Called by the server during {@linkcode server/server.Server.connect | connect()} to pass its supported versions.
     */
    setSupportedProtocolVersions(versions: string[]): void {
        this._supportedProtocolVersions = versions;
    }

    /**
     * Helper to create a JSON error response
     */
    private createJsonErrorResponse(
        status: number,
        code: number,
        message: string,
        options?: { headers?: Record<string, string>; data?: string }
    ): Response {
        const error: { code: number; message: string; data?: string } = { code, message };
        if (options?.data !== undefined) {
            error.data = options.data;
        }
        return Response.json(
            {
                jsonrpc: '2.0',
                error,
                id: null
            },
            {
                status,
                headers: {
                    'Content-Type': 'application/json',
                    ...options?.headers
                }
            }
        );
    }

    /**
     * Validates request headers for DNS rebinding protection.
     * @returns Error response if validation fails, `undefined` if validation passes.
     */
    private validateRequestHeaders(req: Request): Response | undefined {
        // Skip validation if protection is not enabled
        if (!this._enableDnsRebindingProtection) {
            return undefined;
        }

        // Validate Host header if allowedHosts is configured
        if (this._allowedHosts && this._allowedHosts.length > 0) {
            const hostHeader = req.headers.get('host');
            if (!hostHeader || !this._allowedHosts.includes(hostHeader)) {
                const error = `Invalid Host header: ${hostHeader}`;
                this.onerror?.(new Error(error));
                return this.createJsonErrorResponse(403, -32_000, error);
            }
        }

        // Validate Origin header if allowedOrigins is configured
        if (this._allowedOrigins && this._allowedOrigins.length > 0) {
            const originHeader = req.headers.get('origin');
            if (originHeader && !this._allowedOrigins.includes(originHeader)) {
                const error = `Invalid Origin header: ${originHeader}`;
                this.onerror?.(new Error(error));
                return this.createJsonErrorResponse(403, -32_000, error);
            }
        }

        return undefined;
    }

    /**
     * Handles an incoming HTTP request, whether `GET`, `POST`, or `DELETE`
     * Returns a `Response` object (Web Standard)
     */
    async handleRequest(req: Request, options?: HandleRequestOptions): Promise<Response> {
        if (this._closed) {
            return this.createJsonErrorResponse(404, -32_001, 'Session not found');
        }

        // Validate request headers for DNS rebinding protection
        const validationError = this.validateRequestHeaders(req);
        if (validationError) {
            return validationError;
        }

        switch (req.method) {
            case 'POST': {
                return this.handlePostRequest(req, options);
            }
            case 'GET': {
                return this.handleGetRequest(req);
            }
            case 'DELETE': {
                return this.handleDeleteRequest(req);
            }
            default: {
                return this.handleUnsupportedRequest();
            }
        }
    }

    /**
     * Returns true if the client's protocol version supports empty SSE data in
     * priming events (the fix shipped with protocol version `2025-11-25`).
     *
     * The version is checked for membership in this transport instance's
     * supported protocol versions rather than with an open-ended
     * `>= '2025-11-25'` comparison: the value may come from an `initialize`
     * request body, which (unlike the `MCP-Protocol-Version` header) is not
     * validated against `supportedProtocolVersions` before reaching this
     * check. An unknown future version string must not silently enable
     * behavior reserved for versions this transport actually supports.
     */
    private supportsEmptySSEData(protocolVersion: string): boolean {
        return this._supportedProtocolVersions.includes(protocolVersion) && protocolVersion >= '2025-11-25';
    }

    /**
     * Writes a priming event to establish resumption capability.
     * Only sends if `eventStore` is configured (opt-in for resumability) and
     * the client's protocol version supports empty SSE data (a supported
     * version that is >= `2025-11-25`).
     */
    private async writePrimingEvent(
        controller: ReadableStreamDefaultController<Uint8Array>,
        encoder: InstanceType<typeof TextEncoder>,
        streamId: string,
        protocolVersion: string
    ): Promise<void> {
        if (!this._eventStore) {
            return;
        }

        // Priming events have empty data which older clients cannot handle.
        // Only send priming events to clients whose protocol version includes
        // the fix for handling empty SSE data.
        if (!this.supportsEmptySSEData(protocolVersion)) {
            return;
        }

        const primingEventId = await this._eventStore.storeEvent(streamId, {} as JSONRPCMessage);

        let primingEvent = `id: ${primingEventId}\ndata: \n\n`;
        if (this._retryInterval !== undefined) {
            primingEvent = `id: ${primingEventId}\nretry: ${this._retryInterval}\ndata: \n\n`;
        }
        controller.enqueue(encoder.encode(primingEvent));
    }

    /**
     * Handles `GET` requests for SSE stream
     */
    private async handleGetRequest(req: Request): Promise<Response> {
        // The client MUST include an Accept header, listing text/event-stream as a supported content type.
        const acceptHeader = req.headers.get('accept');
        if (!acceptHeader?.includes('text/event-stream')) {
            this.onerror?.(new Error('Not Acceptable: Client must accept text/event-stream'));
            return this.createJsonErrorResponse(406, -32_000, 'Not Acceptable: Client must accept text/event-stream');
        }

        // If an Mcp-Session-Id is returned by the server during initialization,
        // clients using the Streamable HTTP transport MUST include it
        // in the Mcp-Session-Id header on all of their subsequent HTTP requests.
        const sessionError = this.validateSession(req);
        if (sessionError) {
            return sessionError;
        }
        const protocolError = this.validateProtocolVersion(req);
        if (protocolError) {
            return protocolError;
        }

        // Handle resumability: check for Last-Event-ID header
        if (this._eventStore) {
            const lastEventId = req.headers.get('last-event-id');
            if (lastEventId) {
                return this.replayEvents(lastEventId);
            }
        }

        // Check if there's already an active standalone SSE stream for this session
        if (this._streamMapping.get(this._standaloneSseStreamId) !== undefined) {
            // Only one GET SSE stream is allowed per session
            this.onerror?.(new Error('Conflict: Only one SSE stream is allowed per session'));
            return this.createJsonErrorResponse(409, -32_000, 'Conflict: Only one SSE stream is allowed per session');
        }

        const encoder = new TextEncoder();
        let streamController: ReadableStreamDefaultController<Uint8Array>;
        // Captured by cancel/cleanup before it is assigned after stream setup.
        // eslint-disable-next-line prefer-const
        let keepAliveTimer: ReturnType<typeof setInterval> | undefined;

        // Create a ReadableStream with a controller we can use to push SSE events
        const readable = new ReadableStream<Uint8Array>({
            start: controller => {
                streamController = controller;
            },
            cancel: () => {
                if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
                // Stream was cancelled by client. Only drop the mapping when
                // it still points at THIS controller — a stale cancel must not
                // delete a successor stream registered by a later GET/resume.
                if (this._streamMapping.get(this._standaloneSseStreamId)?.controller === streamController) {
                    this._streamMapping.delete(this._standaloneSseStreamId);
                }
            }
        });

        const headers: Record<string, string> = {
            'Content-Type': 'text/event-stream',
            'Cache-Control': 'no-cache, no-transform',
            Connection: 'keep-alive',
            'X-Accel-Buffering': 'no'
        };

        // After initialization, always include the session ID if we have one
        if (this.sessionId !== undefined) {
            headers['mcp-session-id'] = this.sessionId;
        }

        // Store the stream mapping with the controller for pushing data
        this._streamMapping.set(this._standaloneSseStreamId, {
            controller: streamController!,
            encoder,
            cleanup: () => {
                if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
                this._streamMapping.delete(this._standaloneSseStreamId);
                try {
                    streamController!.close();
                } catch {
                    // Controller might already be closed
                }
            }
        });

        keepAliveTimer = this.startKeepAlive(streamController!, encoder);
        return new Response(readable, { headers });
    }

    /**
     * Replays events that would have been sent after the specified event ID
     * Only used when resumability is enabled
     */
    private async replayEvents(lastEventId: string): Promise<Response> {
        if (!this._eventStore) {
            this.onerror?.(new Error('Event store not configured'));
            return this.createJsonErrorResponse(400, -32_000, 'Event store not configured');
        }

        try {
            // If getStreamIdForEventId is available, use it for conflict checking
            let streamId: string | undefined;
            if (this._eventStore.getStreamIdForEventId) {
                streamId = await this._eventStore.getStreamIdForEventId(lastEventId);

                if (!streamId) {
                    this.onerror?.(new Error('Invalid event ID format'));
                    return this.createJsonErrorResponse(400, -32_000, 'Invalid event ID format');
                }

                // Check conflict with the SAME streamId we'll use for mapping
                if (this._streamMapping.get(streamId) !== undefined) {
                    this.onerror?.(new Error('Conflict: Stream already has an active connection'));
                    return this.createJsonErrorResponse(409, -32_000, 'Conflict: Stream already has an active connection');
                }
            }

            const headers: Record<string, string> = {
                'Content-Type': 'text/event-stream',
                'Cache-Control': 'no-cache, no-transform',
                Connection: 'keep-alive',
                'X-Accel-Buffering': 'no'
            };

            if (this.sessionId !== undefined) {
                headers['mcp-session-id'] = this.sessionId;
            }

            // Create a ReadableStream with controller for SSE
            const encoder = new TextEncoder();
            let streamController: ReadableStreamDefaultController<Uint8Array>;
            let keepAliveTimer: ReturnType<typeof setInterval> | undefined;
            let cancelled = false;
            // Captured by the cancel closure below before it's assigned (after
            // replayEventsAfter resolves) — must be `let`.
            // eslint-disable-next-line prefer-const
            let replayedStreamId: string | undefined;

            const readable = new ReadableStream<Uint8Array>({
                start: controller => {
                    streamController = controller;
                },
                cancel: () => {
                    cancelled = true;
                    if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
                    // Stream was cancelled by client — drop the mapping so a
                    // subsequent reconnect with the same Last-Event-ID is not
                    // refused with 409 by the conflict check above. Only delete
                    // when the mapped entry is still THIS closure's controller:
                    // a stale cancel from an earlier resume must not delete a
                    // successor resumed stream a re-poll has since registered.
                    if (replayedStreamId !== undefined && this._streamMapping.get(replayedStreamId)?.controller === streamController) {
                        this._streamMapping.delete(replayedStreamId);
                    }
                }
            });

            // Replay events - returns the streamId for backwards compatibility
            const replayedEventIds = new Set<string>();
            replayedStreamId = await this._eventStore.replayEventsAfter(lastEventId, {
                send: async (eventId: string, message: JSONRPCMessage) => {
                    replayedEventIds.add(eventId);
                    const success = this.writeSSEEvent(streamController!, encoder, message, eventId);
                    if (!success) {
                        try {
                            streamController!.close();
                        } catch {
                            // Controller might already be closed
                        }
                    }
                }
            });

            if (this._closed || cancelled) {
                try {
                    streamController!.close();
                } catch {
                    // Controller already closed/cancelled.
                }
                return this.createJsonErrorResponse(404, -32_001, 'Session not found');
            }

            this._streamMapping.get(replayedStreamId)?.cleanup();
            this._streamMapping.set(replayedStreamId, {
                controller: streamController!,
                encoder,
                replayedEventIds,
                cleanup: () => {
                    if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
                    this._streamMapping.delete(replayedStreamId!);
                    try {
                        streamController!.close();
                    } catch {
                        // Controller might already be closed
                    }
                }
            });

            // If this is a per-request stream and no in-flight request still
            // targets this streamId, the request was already retired by the
            // clean-return path while disconnected and the replay above just
            // delivered the final response. Per the spec the server SHOULD
            // close the SSE stream after the JSON-RPC response — close and
            // unregister so a later reconnect isn't refused with 409. The
            // standalone GET stream is never request-scoped and stays open.
            if (replayedStreamId !== this._standaloneSseStreamId) {
                const hasInFlightRequest = [...this._requestToStreamMapping.values()].includes(replayedStreamId);
                if (!hasInFlightRequest) {
                    this._streamMapping.delete(replayedStreamId);
                    try {
                        streamController!.close();
                    } catch {
                        // Controller might already be closed
                    }
                }
            }

            if (this._streamMapping.get(replayedStreamId)?.controller === streamController!) {
                keepAliveTimer = this.startKeepAlive(streamController!, encoder);
            }
            return new Response(readable, { headers });
        } catch (error) {
            this.onerror?.(error as Error);
            return this.createJsonErrorResponse(500, -32_000, 'Error replaying events');
        }
    }

    /**
     * Writes an event to an SSE stream via controller with proper formatting
     */
    private writeSSEEvent(
        controller: ReadableStreamDefaultController<Uint8Array>,
        encoder: InstanceType<typeof TextEncoder>,
        message: JSONRPCMessage,
        eventId?: string
    ): boolean {
        try {
            let eventData = `event: message\n`;
            // Include event ID if provided - this is important for resumability
            if (eventId) {
                eventData += `id: ${eventId}\n`;
            }
            eventData += `data: ${JSON.stringify(message)}\n\n`;
            controller.enqueue(encoder.encode(eventData));
            return true;
        } catch (error) {
            this.onerror?.(error as Error);
            return false;
        }
    }

    /**
     * Handles unsupported requests (`PUT`, `PATCH`, etc.)
     */
    private handleUnsupportedRequest(): Response {
        this.onerror?.(new Error('Method not allowed.'));
        return Response.json(
            {
                jsonrpc: '2.0',
                error: {
                    code: -32_000,
                    message: 'Method not allowed.'
                },
                id: null
            },
            {
                status: 405,
                headers: {
                    Allow: 'GET, POST, DELETE',
                    'Content-Type': 'application/json'
                }
            }
        );
    }

    /**
     * Handles `POST` requests containing JSON-RPC messages
     */
    private async handlePostRequest(req: Request, options?: HandleRequestOptions): Promise<Response> {
        try {
            // Validate the Accept header
            const acceptHeader = req.headers.get('accept');
            // The client MUST include an Accept header, listing both application/json and text/event-stream as supported content types.
            // Accept is a comma-separated list, so a substring check is the intended semantics here (unlike Content-Type below).
            // eslint-disable-next-line no-restricted-syntax
            if (!acceptHeader?.includes('application/json') || !acceptHeader.includes('text/event-stream')) {
                this.onerror?.(new Error('Not Acceptable: Client must accept both application/json and text/event-stream'));
                return this.createJsonErrorResponse(
                    406,
                    -32_000,
                    'Not Acceptable: Client must accept both application/json and text/event-stream'
                );
            }

            // Parsed media type, never a substring match — see
            // isJsonContentType. This check stays here for hand-wired
            // transports; via createMcpHandler the entry's own check answers
            // first.
            const ct = req.headers.get('content-type');
            if (!isJsonContentType(ct)) {
                this.onerror?.(new Error('Unsupported Media Type: Content-Type must be application/json'));
                return this.createJsonErrorResponse(415, -32_000, 'Unsupported Media Type: Content-Type must be application/json');
            }

            const request = req;

            let rawMessage;
            if (options?.parsedBody === undefined) {
                try {
                    rawMessage = await req.json();
                } catch (error) {
                    this.onerror?.(error as Error);
                    return this.createJsonErrorResponse(400, -32_700, 'Parse error: Invalid JSON');
                }
            } else {
                rawMessage = options.parsedBody;
            }

            let messages: JSONRPCMessage[];

            // handle batch and single messages
            try {
                messages = Array.isArray(rawMessage)
                    ? rawMessage.map(msg => JSONRPCMessageSchema.parse(msg))
                    : [JSONRPCMessageSchema.parse(rawMessage)];
            } catch (error) {
                this.onerror?.(error as Error);
                return this.createJsonErrorResponse(400, -32_700, 'Parse error: Invalid JSON-RPC message');
            }

            if (this._closed) {
                return this.createJsonErrorResponse(404, -32_001, 'Session not found');
            }

            // Check if this is an initialization request
            // https://spec.modelcontextprotocol.io/specification/2025-03-26/basic/lifecycle/
            // The schema-validated guard (types/guards.ts → types/schemas.ts —
            // NOT a wire/rev* import) gates a transport state mutation: a
            // malformed `initialize` must NOT set `_initialized = true` before
            // the protocol layer rejects it.
            const isInitializationRequest = messages.some(element => isInitializeRequest(element));
            if (isInitializationRequest) {
                // If it's a server with session management and the session ID is already set we should reject the request
                // to avoid re-initialization.
                if (this._initialized && this.sessionId !== undefined) {
                    this.onerror?.(new Error('Invalid Request: Server already initialized'));
                    return this.createJsonErrorResponse(400, -32_600, 'Invalid Request: Server already initialized');
                }
                if (messages.length > 1) {
                    this.onerror?.(new Error('Invalid Request: Only one initialization request is allowed'));
                    return this.createJsonErrorResponse(400, -32_600, 'Invalid Request: Only one initialization request is allowed');
                }
                this.sessionId = this.sessionIdGenerator?.();
                this._initialized = true;

                // If we have a session ID and an onsessioninitialized handler, call it immediately
                // This is needed in cases where the server needs to keep track of multiple sessions
                if (this.sessionId && this._onsessioninitialized) {
                    await Promise.resolve(this._onsessioninitialized(this.sessionId));
                }
            }
            if (!isInitializationRequest) {
                // If an Mcp-Session-Id is returned by the server during initialization,
                // clients using the Streamable HTTP transport MUST include it
                // in the Mcp-Session-Id header on all of their subsequent HTTP requests.
                const sessionError = this.validateSession(req);
                if (sessionError) {
                    return sessionError;
                }
                // Mcp-Protocol-Version header is required for all requests after initialization.
                const protocolError = this.validateProtocolVersion(req);
                if (protocolError) {
                    return protocolError;
                }
            }

            if (this._closed) {
                return this.createJsonErrorResponse(404, -32_001, 'Session not found');
            }

            // check if it contains requests
            const hasRequests = messages.some(element => isJSONRPCRequest(element));

            if (!hasRequests) {
                // if it only contains notifications or responses, return 202
                for (const message of messages) {
                    this.onmessage?.(message, { authInfo: options?.authInfo, request });
                }
                return new Response(null, { status: 202 });
            }

            // The default behavior is to use SSE streaming
            // but in some cases server will return JSON responses
            const streamId = crypto.randomUUID();

            // Extract protocol version for priming event decision.
            // For initialize requests, get from request params.
            // For other requests, get from header (already validated).
            const initRequest = messages.find(m => isInitializeRequest(m));
            const clientProtocolVersion = initRequest
                ? initRequest.params.protocolVersion
                : (req.headers.get('mcp-protocol-version') ?? DEFAULT_NEGOTIATED_PROTOCOL_VERSION);

            if (this._enableJsonResponse) {
                // For JSON response mode, return a Promise that resolves when all responses are ready
                return new Promise<Response>(resolve => {
                    this._streamMapping.set(streamId, {
                        resolveJson: resolve,
                        cleanup: () => {
                            this._streamMapping.delete(streamId);
                        }
                    });

                    for (const message of messages) {
                        if (isJSONRPCRequest(message)) {
                            this._requestToStreamMapping.set(message.id, streamId);
                        }
                    }

                    for (const message of messages) {
                        this.onmessage?.(message, { authInfo: options?.authInfo, request });
                    }
                });
            }

            // SSE streaming mode - use ReadableStream with controller for more reliable data pushing
            const encoder = new TextEncoder();
            let streamController: ReadableStreamDefaultController<Uint8Array>;
            let keepAliveTimer: ReturnType<typeof setInterval> | undefined;

            const readable = new ReadableStream<Uint8Array>({
                start: controller => {
                    streamController = controller;
                },
                cancel: () => {
                    if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
                    // Stream was cancelled by client. Only drop the mapping
                    // when it still points at THIS controller — a stale cancel
                    // (firing after a Last-Event-ID reconnect registered a
                    // resumed stream under the same streamId) must not delete
                    // the successor.
                    if (this._streamMapping.get(streamId)?.controller === streamController) {
                        this._streamMapping.delete(streamId);
                    }
                }
            });

            const headers: Record<string, string> = {
                'Content-Type': 'text/event-stream',
                'Cache-Control': 'no-cache, no-transform',
                Connection: 'keep-alive',
                'X-Accel-Buffering': 'no'
            };

            // After initialization, always include the session ID if we have one
            if (this.sessionId !== undefined) {
                headers['mcp-session-id'] = this.sessionId;
            }

            // Store the response for this request to send messages back through this connection
            // We need to track by request ID to maintain the connection
            for (const message of messages) {
                if (isJSONRPCRequest(message)) {
                    this._streamMapping.set(streamId, {
                        controller: streamController!,
                        encoder,
                        cleanup: () => {
                            if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
                            this._streamMapping.delete(streamId);
                            try {
                                streamController!.close();
                            } catch {
                                // Controller might already be closed
                            }
                        }
                    });
                    this._requestToStreamMapping.set(message.id, streamId);
                }
            }

            // Write priming event if event store is configured (after mapping is set up)
            await this.writePrimingEvent(streamController!, encoder, streamId, clientProtocolVersion);

            // handle each message
            for (const message of messages) {
                // Build closeSSEStream callback for requests when eventStore is configured
                // AND client supports resumability (a supported protocol version >= 2025-11-25).
                // Old clients can't resume if the stream is closed early because they
                // didn't receive a priming event with an event ID.
                let closeSSEStream: (() => void) | undefined;
                let closeStandaloneSSEStream: (() => void) | undefined;
                if (isJSONRPCRequest(message) && this._eventStore && this.supportsEmptySSEData(clientProtocolVersion)) {
                    closeSSEStream = () => {
                        this.closeSSEStream(message.id);
                    };
                    closeStandaloneSSEStream = () => {
                        this.closeStandaloneSSEStream();
                    };
                }

                this.onmessage?.(message, { authInfo: options?.authInfo, request, closeSSEStream, closeStandaloneSSEStream });
            }
            // The server SHOULD NOT close the SSE stream before sending all JSON-RPC responses
            // This will be handled by the send() method when responses are ready

            if (this._streamMapping.get(streamId)?.controller === streamController!) {
                keepAliveTimer = this.startKeepAlive(streamController!, encoder);
            }
            return new Response(readable, { status: 200, headers });
        } catch (error) {
            // return JSON-RPC formatted error
            this.onerror?.(error as Error);
            return this.createJsonErrorResponse(400, -32_700, 'Parse error', { data: String(error) });
        }
    }

    /**
     * Handles `DELETE` requests to terminate sessions
     */
    private async handleDeleteRequest(req: Request): Promise<Response> {
        const sessionError = this.validateSession(req);
        if (sessionError) {
            return sessionError;
        }
        const protocolError = this.validateProtocolVersion(req);
        if (protocolError) {
            return protocolError;
        }

        try {
            await Promise.resolve(this._onsessionclosed?.(this.sessionId!));
            return new Response(null, { status: 200 });
        } finally {
            await this.close();
        }
    }

    /**
     * Validates session ID for non-initialization requests.
     * Returns `Response` error if invalid, `undefined` otherwise
     */
    private validateSession(req: Request): Response | undefined {
        if (this.sessionIdGenerator === undefined) {
            // If the sessionIdGenerator ID is not set, the session management is disabled
            // and we don't need to validate the session ID
            return undefined;
        }
        if (!this._initialized) {
            // If the server has not been initialized yet, reject all requests
            this.onerror?.(new Error('Bad Request: Server not initialized'));
            return this.createJsonErrorResponse(400, -32_000, 'Bad Request: Server not initialized');
        }

        const sessionId = req.headers.get('mcp-session-id');

        if (!sessionId) {
            // Non-initialization requests without a session ID should return 400 Bad Request
            this.onerror?.(new Error('Bad Request: Mcp-Session-Id header is required'));
            return this.createJsonErrorResponse(400, -32_000, 'Bad Request: Mcp-Session-Id header is required');
        }

        if (sessionId !== this.sessionId) {
            // Reject requests with invalid session ID with 404 Not Found
            this.onerror?.(new Error('Session not found'));
            return this.createJsonErrorResponse(404, -32_001, 'Session not found');
        }

        return undefined;
    }

    /**
     * Validates the `MCP-Protocol-Version` header on incoming requests.
     *
     * For initialization: Version negotiation handles unknown versions gracefully
     * (server responds with its supported version).
     *
     * For subsequent requests with `MCP-Protocol-Version` header:
     * - Accept if in supported list
     * - 400 if unsupported
     *
     * For HTTP requests without the `MCP-Protocol-Version` header:
     * - Accept and default to the version negotiated at initialization
     */
    private validateProtocolVersion(req: Request): Response | undefined {
        const protocolVersion = req.headers.get('mcp-protocol-version');

        if (protocolVersion !== null && !this._supportedProtocolVersions.includes(protocolVersion)) {
            const error = `Bad Request: Unsupported protocol version: ${protocolVersion} (supported versions: ${this._supportedProtocolVersions.join(', ')})`;
            this.onerror?.(new Error(error));
            return this.createJsonErrorResponse(400, -32_000, error);
        }
        return undefined;
    }

    async close(): Promise<void> {
        if (this._closed) {
            return;
        }
        this._closed = true;

        // Close all SSE connections
        for (const { cleanup } of this._streamMapping.values()) {
            cleanup();
        }
        this._streamMapping.clear();

        // Clear any pending responses
        this._requestResponseMap.clear();
        this.onclose?.();
    }

    /**
     * Close an SSE stream for a specific request, triggering client reconnection.
     * Use this to implement polling behavior during long-running operations -
     * client will reconnect after the retry interval specified in the priming event.
     */
    closeSSEStream(requestId: RequestId): void {
        const streamId = this._requestToStreamMapping.get(requestId);
        if (!streamId) return;

        const stream = this._streamMapping.get(streamId);
        if (stream) {
            stream.cleanup();
        }
    }

    /**
     * Close the standalone `GET` SSE stream, triggering client reconnection.
     * Use this to implement polling behavior for server-initiated notifications.
     */
    closeStandaloneSSEStream(): void {
        const stream = this._streamMapping.get(this._standaloneSseStreamId);
        if (stream) {
            stream.cleanup();
        }
    }

    async send(message: JSONRPCMessage, options?: { relatedRequestId?: RequestId }): Promise<void> {
        let requestId = options?.relatedRequestId;
        if (isJSONRPCResultResponse(message) || isJSONRPCErrorResponse(message)) {
            // If the message is a response, use the request ID from the message
            requestId = message.id;
        }

        // Check if this message should be sent on the standalone SSE stream (no request ID)
        // Ignore notifications from tools (which have relatedRequestId set)
        // Those will be sent via dedicated response SSE streams
        if (requestId === undefined) {
            // For standalone SSE streams, we can only send requests and notifications
            if (isJSONRPCResultResponse(message) || isJSONRPCErrorResponse(message)) {
                throw new Error('Cannot send a response on a standalone SSE stream unless resuming a previous client request');
            }

            // Generate and store event ID if event store is provided
            // Store even if stream is disconnected so events can be replayed on reconnect
            let eventId: string | undefined;
            if (this._eventStore) {
                // Stores the event and gets the generated event ID
                eventId = await this._eventStore.storeEvent(this._standaloneSseStreamId, message);
            }

            const standaloneSse = this._streamMapping.get(this._standaloneSseStreamId);
            if (standaloneSse === undefined) {
                // Stream is disconnected - event is stored for replay, nothing more to do
                return;
            }

            // Send the message to the standalone SSE stream — unless the
            // resumed stream's replay already delivered this exact eventId
            // (identity dedup; mirrors the per-request path below).
            if (
                standaloneSse.controller &&
                standaloneSse.encoder &&
                (eventId === undefined || !standaloneSse.replayedEventIds?.has(eventId))
            ) {
                this.writeSSEEvent(standaloneSse.controller, standaloneSse.encoder, message, eventId);
            }
            return;
        }

        // Get the response for this request
        const streamId = this._requestToStreamMapping.get(requestId);
        if (!streamId) {
            throw new Error(`No connection established for request ID: ${String(requestId)}`);
        }

        let stream = this._streamMapping.get(streamId);

        if (!this._enableJsonResponse) {
            // Store FIRST so request-related events emitted while the per-request
            // stream is disconnected (e.g. after `closeSSE()` or a transient
            // client drop) are replayed on Last-Event-ID reconnect — same
            // store-first semantics as the standalone path above. Storage is
            // keyed on request-in-flight (`_requestToStreamMapping` resolved
            // `streamId` above), not on whether a live SSE writer currently
            // exists: `_streamMapping` tracks the delivery target only. Per
            // 2025-11-25 transports.mdx, disconnection SHOULD NOT be
            // interpreted as the client cancelling its request.
            let eventId: string | undefined;
            if (this._eventStore) {
                eventId = await this._eventStore.storeEvent(streamId, message);
                // Re-read after the await: a Last-Event-ID reconnect during
                // storeEvent() may have registered a resumed stream under this
                // streamId (mirrors the standalone path's post-await read).
                stream = this._streamMapping.get(streamId);
            }
            // Write the event to the response stream — unless the resumed
            // stream's replay already delivered this exact eventId (the store
            // committed before replay scanned, so replay wrote it; identity
            // dedup only, no ordering assumption).
            if (stream?.controller && stream?.encoder && (eventId === undefined || !stream.replayedEventIds?.has(eventId))) {
                this.writeSSEEvent(stream.controller, stream.encoder, message, eventId);
            }
        }

        if (isJSONRPCResultResponse(message) || isJSONRPCErrorResponse(message)) {
            this._requestResponseMap.set(requestId, message);
            const relatedIds = [...this._requestToStreamMapping.entries()].filter(([_, sid]) => sid === streamId).map(([id]) => id);

            // Check if we have responses for all requests using this connection
            const allResponsesReady = relatedIds.every(id => this._requestResponseMap.has(id));

            if (allResponsesReady) {
                if (!stream) {
                    if (this._enableJsonResponse) {
                        // JSON-mode requires a resolveJson sink; with no stream entry the
                        // response is undeliverable.
                        throw new Error(`No connection established for request ID: ${String(requestId)}`);
                    }
                    if (!this._eventStore) {
                        // SSE-mode with no live writer and no event store: the
                        // response is undeliverable AND not stored. Surface via
                        // onerror so the drop is observable (matching pre-PR
                        // behaviour), then run the bookkeeping cleanup so the
                        // request id is retired.
                        this.onerror?.(
                            new Error(
                                `Response for request ID ${String(requestId)} is undeliverable: per-request stream is disconnected and no eventStore is configured`
                            )
                        );
                        for (const id of relatedIds) {
                            this._requestResponseMap.delete(id);
                            this._requestToStreamMapping.delete(id);
                        }
                        return;
                    }
                    // SSE-mode with no live writer and an event store configured:
                    // the response was stored above for replay on Last-Event-ID
                    // reconnect. Return cleanly after running the bookkeeping
                    // cleanup so the request id is retired.
                    for (const id of relatedIds) {
                        this._requestResponseMap.delete(id);
                        this._requestToStreamMapping.delete(id);
                    }
                    return;
                }
                if (this._enableJsonResponse && stream.resolveJson) {
                    // All responses ready, send as JSON
                    const headers: Record<string, string> = {
                        'Content-Type': 'application/json'
                    };
                    if (this.sessionId !== undefined) {
                        headers['mcp-session-id'] = this.sessionId;
                    }

                    const responses = relatedIds.map(id => this._requestResponseMap.get(id)!);

                    if (responses.length === 1) {
                        stream.resolveJson(Response.json(responses[0], { status: 200, headers }));
                    } else {
                        stream.resolveJson(Response.json(responses, { status: 200, headers }));
                    }
                    stream.cleanup();
                } else {
                    // End the SSE stream
                    stream.cleanup();
                }
                // Clean up
                for (const id of relatedIds) {
                    this._requestResponseMap.delete(id);
                    this._requestToStreamMapping.delete(id);
                }
            }
        }
    }
}
/**
 * `createMcpHandler` — the HTTP entry point for serving the 2026-07-28 protocol
 * revision, with old-school stateless 2025-era serving as the default fallback.
 *
 * The entry classifies every inbound HTTP request exactly once (body-primary,
 * via {@linkcode classifyInboundRequest}) and routes it:
 *
 * - Requests carrying the per-request `_meta` envelope are served on the modern
 *   path: a fresh server instance from the consumer's factory, marked as
 *   serving the claimed revision, connected to a single-exchange per-request
 *   transport.
 * - Requests without an envelope claim (including `initialize`, GET/DELETE
 *   session operations, and 2025-era notification POSTs) are legacy traffic.
 *   By default they are served per request through the stateless idiom from
 *   the same factory (`legacy: 'stateless'`); with `legacy: 'reject'` the
 *   endpoint is modern-only strict and answers the documented rejection cells
 *   instead — there is no 2025 serving in that mode.
 *
 * There is no handler-valued `legacy` option: an existing legacy deployment
 * (for example a sessionful streamable HTTP wiring) keeps serving 2025 traffic
 * by routing in user land with {@linkcode isLegacyRequest} — the entry's own
 * classification step, exported as a predicate — in front of a strict
 * (`legacy: 'reject'`) handler.
 *
 * The entry performs no Origin/Host validation (mount the origin/host
 * validation middleware in front of it) and no token verification — `authInfo`
 * is pass-through from the caller and is never derived from request headers.
 */
import type {
    AuthInfo,
    ClientCapabilities,
    Implementation,
    InboundClassificationOutcome,
    InboundLadderRejection,
    InboundLegacyRoute,
    InboundModernRoute,
    RequestId
} from '@modelcontextprotocol/core-internal';
import {
    classifyInboundRequest,
    CLIENT_CAPABILITIES_META_KEY,
    CLIENT_INFO_META_KEY,
    httpStatusForErrorCode,
    isJsonContentType,
    mediaTypeEssence,
    missingClientCapabilities,
    MissingRequiredClientCapabilityError,
    modernOnlyStrictRejection,
    requestMetaOf,
    requiredClientCapabilitiesForRequest,
    scanXMcpHeaderDeclarations,
    SdkError,
    SdkErrorCode,
    setNegotiatedProtocolVersion,
    SUPPORTED_MODERN_PROTOCOL_VERSIONS,
    UnsupportedProtocolVersionError,
    validateMcpParamHeaders,
    validateStandardRequestHeaders
} from '@modelcontextprotocol/core-internal';

import { invoke } from './invoke';
import { createListenRouter, DEFAULT_MAX_SUBSCRIPTIONS } from './listenRouter';
import { McpServer } from './mcp';
import type { PerRequestResponseMode } from './perRequestTransport';
import type { Server } from './server';
import { installModernOnlyHandlers, seedClientIdentityFromEnvelope, serverIdentityOf } from './server';
import type { ServerEventBus, ServerNotifier } from './serverEventBus';
import { createServerNotifier, InMemoryServerEventBus } from './serverEventBus';
import { DEFAULT_SSE_KEEP_ALIVE_MS } from './sseKeepAlive';
import { WebStandardStreamableHTTPServerTransport } from './streamableHttp';

/* ------------------------------------------------------------------------ *
 * Factory and handler types
 * ------------------------------------------------------------------------ */

/**
 * Construction context handed to an {@linkcode McpServerFactory}.
 *
 * Both serving entries call the factory with this context whenever they need
 * a fresh instance: {@linkcode createMcpHandler} once per HTTP request, and
 * `serveStdio` (from `@modelcontextprotocol/server/stdio`) once per
 * connection — plus once for a `server/discover` probe instance that is
 * discarded again if the client falls back to `initialize`.
 *
 * Zero-argument factories remain assignable unchanged; the context exists for
 * factories that vary by principal or era (for example multi-tenant servers
 * keyed off `authInfo`, or a factory that registers extra surface only for one
 * era).
 */
export interface McpRequestContext {
    /**
     * The protocol era the constructed instance will serve: `modern` for
     * 2026-07-28 (per-request envelope) traffic, `legacy` for 2025-era
     * traffic. Under {@linkcode createMcpHandler} a `legacy` instance serves
     * one request through the stateless legacy fallback (the default —
     * `legacy: 'reject'` endpoints are strict and never construct one); under
     * `serveStdio` it serves a connection that opened with the 2025 handshake
     * and stays pinned to that era for its lifetime.
     */
    era: 'legacy' | 'modern';
    /**
     * Validated authentication information passed by the caller of the
     * handler face (pass-through; HTTP only — `serveStdio` never sets it).
     */
    authInfo?: AuthInfo;
    /** The original HTTP request being served, when available (HTTP only — `serveStdio` never sets it). */
    requestInfo?: Request;
}

/**
 * A factory producing a fresh {@linkcode McpServer} (or low-level
 * {@linkcode Server}) instance for one serving unit: one HTTP request under
 * {@linkcode createMcpHandler}, or one connection (or one discarded
 * `server/discover` probe) under `serveStdio`. The same factory backs every
 * era either entry serves — define your tools, resources and prompts once and
 * serve them to both eras.
 */
export type McpServerFactory = (ctx: McpRequestContext) => McpServer | Server | Promise<McpServer | Server>;

/** Caller-provided per-request inputs for {@linkcode McpHttpHandler.fetch} and fetch-shaped legacy handlers ({@linkcode LegacyHttpHandler}). */
export interface McpHandlerRequestOptions {
    /**
     * Validated authentication information for the request. Strictly
     * pass-through: the handler never populates this from request headers and
     * performs no token verification of its own.
     */
    authInfo?: AuthInfo;
    /** A pre-parsed JSON request body (e.g. `req.body` from `express.json()`). */
    parsedBody?: unknown;
}

/**
 * A fetch-shaped handler serving 2025-era traffic: the shape produced by
 * {@linkcode legacyStatelessFallback}, and the shape a hand-wired composition
 * routes legacy requests to (see {@linkcode isLegacyRequest}). It is not a
 * `legacy` option value — the entry's own legacy serving is selected by the
 * `'stateless' | 'reject'` posture only.
 */
export type LegacyHttpHandler = (request: Request, options?: McpHandlerRequestOptions) => Promise<Response>;

/** Options for {@linkcode createMcpHandler}. */
export interface CreateMcpHandlerOptions {
    /**
     * How 2025-era (non-envelope) traffic is served:
     *
     * - `'stateless'` (the default, also when the option is omitted) —
     *   old-school stateless serving: each legacy request is answered by a
     *   fresh instance from the same factory over a streamable HTTP transport
     *   constructed with only `sessionIdGenerator: undefined` (the established
     *   stateless idiom). Because serving is per-request and stateless, GET and
     *   DELETE (2025 session operations) are answered with `405` /
     *   `Method not allowed.`.
     * - `'reject'` — modern-only strict: legacy-classified requests are
     *   rejected with the unsupported-protocol-version error naming the
     *   endpoint's supported revisions (legacy-classified notifications are
     *   acknowledged with `202` and dropped). **There is no 2025 serving in
     *   this mode.**
     *
     * There is no handler-valued option: to keep an existing legacy deployment
     * (for example a sessionful streamable HTTP wiring) serving 2025 traffic
     * next to this entry, route in user land with {@linkcode isLegacyRequest}
     * in front of a `legacy: 'reject'` handler — see that predicate's
     * documentation for the pattern.
     */
    legacy?: 'stateless' | 'reject';
    /** Callback for out-of-band errors and rejected requests (reporting only; it never alters the response). */
    onerror?: (error: Error) => void;
    /**
     * Response shaping for modern (2026-07-28) request exchanges:
     *
     * - `'auto'` (default) — a single JSON body unless the handler emits a
     *   related message before its result, in which case the response upgrades
     *   to an SSE stream.
     * - `'sse'` — always stream.
     * - `'json'` — never stream. **Mid-call notifications (progress, logging,
     *   any related message emitted before the result) are dropped** — only the
     *   terminal result is delivered. Listen-class subscription streams are
     *   always served over SSE regardless of this setting.
     */
    responseMode?: PerRequestResponseMode;
    /**
     * The change-event bus `subscriptions/listen` streams subscribe to.
     *
     * When omitted, an in-process {@link InMemoryServerEventBus} is created
     * and the returned handler's `notify` sugar publishes onto it.
     * Multi-process deployments supply their own implementation over their
     * pub/sub backend; the same instance can be shared across handlers.
     */
    bus?: ServerEventBus;
    /**
     * Reject a new `subscriptions/listen` with `-32603` 'Subscription limit
     * reached' (in-band, HTTP 200, before the ack) when this many subscription
     * streams are already open on this handler.
     * @default 1024
     */
    maxSubscriptions?: number;
    /**
     * SSE comment-frame keepalive interval for every SSE stream this handler
     * serves. In modern `auto` mode it starts after SSE upgrade. Set to `0` to disable.
     * @default 15000
     */
    keepAliveMs?: number;
}

/**
 * The handler returned by {@linkcode createMcpHandler}: a web-standard
 * `{ fetch, close, notify, bus }` object — the shape Workers/Bun/Deno expect
 * from `export default`. `fetch` is an arrow-assigned bound property: it can be
 * detached and passed around (`const { fetch } = handler`) without losing its
 * binding.
 *
 * Node frameworks (Express, Fastify, plain `node:http`) wrap the handler once
 * with `toNodeHandler(handler)` from `@modelcontextprotocol/node`.
 */
export interface McpHttpHandler {
    /** Web-standard face: serve one HTTP request and resolve with the response. */
    fetch: (request: Request, options?: McpHandlerRequestOptions) => Promise<Response>;
    /**
     * Tears down the modern leg: aborts in-flight modern exchanges and closes
     * their per-request instances. Legacy serving is unaffected — the
     * stateless fallback is per-request by construction and holds nothing
     * between exchanges.
     */
    close: () => Promise<void>;
    /**
     * Typed publish-side facade over the handler's `subscriptions/listen` bus:
     * each method publishes the corresponding change event to every open
     * subscription stream that opted in to that notification type.
     *
     * Safe to call when no subscription is open (no-op).
     */
    notify: ServerNotifier;
    /**
     * The change-event bus this handler's `subscriptions/listen` streams
     * subscribe to (the supplied `bus` option, or the auto-created in-process
     * default).
     */
    bus: ServerEventBus;
}

/* ------------------------------------------------------------------------ *
 * Shared response helpers
 * ------------------------------------------------------------------------ */

/**
 * The JSON-RPC id to echo on an entry-built error response: the body's `id`
 * when the body is a single JSON-RPC request whose id is a string or number,
 * `null` otherwise. Error responses must carry the id of the request they
 * correspond to whenever it could be read; `null` is reserved for the cases
 * where no single request id is determinable — unparseable bodies, body-less
 * methods, notifications, posted responses and batch arrays.
 */
function echoableRequestId(body: unknown): RequestId | null {
    if (body === null || typeof body !== 'object' || Array.isArray(body)) {
        return null;
    }
    const { method, id } = body as { method?: unknown; id?: unknown };
    if (typeof method !== 'string') {
        return null;
    }
    return typeof id === 'string' || typeof id === 'number' ? id : null;
}

function jsonRpcErrorResponse(httpStatus: number, code: number, message: string, data?: unknown, id: RequestId | null = null): Response {
    return Response.json(
        {
            jsonrpc: '2.0',
            error: { code, message, ...(data !== undefined && { data }) },
            id
        },
        { status: httpStatus }
    );
}

function rejectionResponse(rejection: InboundLadderRejection, id: RequestId | null = null): Response {
    return jsonRpcErrorResponse(rejection.httpStatus, rejection.code, rejection.message, rejection.data, id);
}

function toError(value: unknown): Error {
    return value instanceof Error ? value : new Error(String(value));
}

function internalServerErrorResponse(id: RequestId | null = null): Response {
    return jsonRpcErrorResponse(500, -32_603, 'Internal server error', undefined, id);
}

/* ------------------------------------------------------------------------ *
 * The default legacy fallback
 * ------------------------------------------------------------------------ */

/**
 * The entry's default legacy serving (`legacy: 'stateless'`): per-request
 * stateless serving of 2025-era traffic using the same factory as the modern
 * path. Exported as a standalone building block for hand-wired compositions
 * (for example mounting legacy stateless serving on its own route next to a
 * strict modern endpoint).
 *
 * Each POST is served by a fresh instance from the factory connected to a
 * fresh streamable HTTP transport constructed with only
 * `sessionIdGenerator: undefined` — the established stateless idiom, unchanged.
 * Because serving is per-request and stateless, GET and DELETE (2025 session
 * operations) are answered with `405` / `Method not allowed.`, exactly like the
 * canonical stateless example.
 *
 * The optional `onerror` callback receives factory and serving failures on
 * this leg (reporting only — the response stays the 500 internal-error body).
 * The entry passes its own `onerror` here when expanding the default, so
 * legacy-leg failures are never silently swallowed.
 */
function createLegacyStatelessFallback(
    factory: McpServerFactory,
    onerror?: (error: Error) => void,
    keepAliveMs?: number
): LegacyHttpHandler {
    return async (request, options) => {
        if (request.method.toUpperCase() !== 'POST') {
            return jsonRpcErrorResponse(405, -32_000, 'Method not allowed.');
        }
        try {
            const product = await factory({
                era: 'legacy',
                ...(options?.authInfo !== undefined && { authInfo: options.authInfo }),
                requestInfo: request
            });
            const transport = new WebStandardStreamableHTTPServerTransport({
                sessionIdGenerator: undefined,
                ...(keepAliveMs !== undefined && { keepAliveMs })
            });
            await product.connect(transport);

            const teardown = () => {
                void transport.close().catch(() => {});
                void product.close().catch(() => {});
            };
            // Tear the per-request pair down when the client goes away before
            // the exchange completes.
            request.signal?.addEventListener('abort', teardown, { once: true });

            const response = await transport.handleRequest(request, {
                ...(options?.authInfo !== undefined && { authInfo: options.authInfo }),
                ...(options?.parsedBody !== undefined && { parsedBody: options.parsedBody })
            });
            if (response.body === null || mediaTypeEssence(response.headers.get('content-type')) !== 'text/event-stream') {
                // Non-streaming exchange (a buffered JSON body or a body-less
                // ack): the response is complete, release the pair now.
                teardown();
                return response;
            }
            // Streaming exchange: the legacy transport answers request-bearing
            // POSTs over SSE, so the exchange is only over once the stream has
            // been fully delivered. Wrap the body so the pair is torn down on
            // completion, on a producer error, or when the consumer abandons
            // the stream — the fetch-world analog of the canonical stateless
            // example's close-on-response-end.
            const reader = response.body.getReader();
            let toreDown = false;
            const completeExchange = () => {
                if (!toreDown) {
                    toreDown = true;
                    teardown();
                }
            };
            const monitoredBody = new ReadableStream<Uint8Array>({
                pull: async controller => {
                    try {
                        const { done, value } = await reader.read();
                        if (done) {
                            completeExchange();
                            controller.close();
                            return;
                        }
                        if (value !== undefined) {
                            controller.enqueue(value);
                        }
                    } catch (error) {
                        completeExchange();
                        controller.error(error);
                    }
                },
                cancel: reason => {
                    completeExchange();
                    return reader.cancel(reason).catch(() => {});
                }
            });
            return new Response(monitoredBody, {
                status: response.status,
                statusText: response.statusText,
                headers: response.headers
            });
        } catch (error) {
            try {
                onerror?.(toError(error));
            } catch {
                // Reporting must never alter the response.
            }
            return internalServerErrorResponse(echoableRequestId(options?.parsedBody));
        }
    };
}

export function legacyStatelessFallback(factory: McpServerFactory, onerror?: (error: Error) => void): LegacyHttpHandler {
    return createLegacyStatelessFallback(factory, onerror);
}

/* ------------------------------------------------------------------------ *
 * The entry's classification step (shared with isLegacyRequest)
 * ------------------------------------------------------------------------ */

/** The outcome of the entry's classification step for one inbound HTTP request. */
type EntryClassification =
    /** The body bytes could not be read at all (a failing stream, not malformed JSON). */
    | { step: 'unreadable-body' }
    /** A POST with an empty or non-JSON body: nothing to classify, so there is no envelope claim. */
    | { step: 'no-json-body'; forwardRequest: Request }
    /** A classifiable request, with the classifier's routing outcome. */
    | { step: 'classified'; outcome: InboundClassificationOutcome; body: unknown; parsedBody: unknown; forwardRequest: Request };

/**
 * The entry's classification step: read the request body exactly once (unless
 * a pre-parsed body is supplied) and classify the request with
 * {@linkcode classifyInboundRequest}. This is the single code path behind both
 * {@linkcode createMcpHandler}'s routing and the exported
 * {@linkcode isLegacyRequest} predicate, so the two can never disagree.
 *
 * Pass `needsForward: false` when the caller never reads `forwardRequest` —
 * the body-preserving clone is then skipped and `forwardRequest` is the
 * (consumed) input request.
 */
async function classifyEntryRequest(request: Request, providedParsedBody?: unknown, needsForward = true): Promise<EntryClassification> {
    const httpMethod = request.method.toUpperCase();

    let body: unknown;
    let parsedBody = providedParsedBody;
    let forwardRequest = request;
    let unparseable = false;

    if (httpMethod === 'POST') {
        if (parsedBody === undefined) {
            // Read the body exactly once for classification, keeping an unread
            // copy of the original bytes for the legacy leg (web-standard
            // request bodies are single-use) when the caller needs it.
            if (needsForward) {
                forwardRequest = request.clone();
            }
            let bodyText: string;
            try {
                bodyText = await request.text();
            } catch {
                return { step: 'unreadable-body' };
            }
            try {
                body = bodyText.length === 0 ? undefined : JSON.parse(bodyText);
            } catch {
                unparseable = true;
            }
            if (!unparseable && body !== undefined) {
                parsedBody = body;
            }
        } else {
            body = parsedBody;
        }

        if (unparseable || body === undefined) {
            return { step: 'no-json-body', forwardRequest };
        }
    }

    const outcome = classifyInboundRequest({
        httpMethod,
        protocolVersionHeader: request.headers.get('mcp-protocol-version') ?? undefined,
        mcpMethodHeader: request.headers.get('mcp-method') ?? undefined,
        mcpNameHeader: request.headers.get('mcp-name') ?? undefined,
        ...(body !== undefined && { body })
    });
    return { step: 'classified', outcome, body, parsedBody, forwardRequest };
}

/**
 * Whether {@linkcode createMcpHandler} would route this request to its legacy
 * (2025-era) serving rather than the modern (2026-07-28) path.
 *
 * Call it with just the request: `await isLegacyRequest(request)`. For a
 * `POST` the body is read from an internal clone, so the request you pass
 * stays fully readable for whichever handler you route it to — no second
 * argument is needed. (In a Node `(req, res)` handler, build that `Request`
 * with `toWebRequest(req)` from `@modelcontextprotocol/node`; behind a body
 * parser, which has already drained the Node stream, build it as
 * `toWebRequest(req, req.body)` so the bytes come from the parsed body —
 * either way the predicate still takes just the request.) The optional
 * `parsedBody` is a perf escape hatch for a body you already hold parsed:
 * pass it and the predicate classifies from the value directly, reading and
 * cloning nothing. It is needed, not just faster, when the request's own
 * body was already read — the internal clone is then impossible (cloning a
 * used body throws a `TypeError`), so such a single-argument call rejects
 * instead of guessing.
 *
 * This is the entry's own classification step exported as a predicate — it
 * runs exactly the code `createMcpHandler` runs to make the routing decision,
 * not a re-implementation — so a hand-wired composition that branches on it
 * can never disagree with the entry. It is classification only: hand-wired
 * compositions must validate Content-Type themselves (415 for POSTs whose
 * media type is not `application/json`, via {@linkcode isJsonContentType})
 * before dispatching either leg — routing the legacy leg into the SDK
 * transports gets their built-in check, but a custom modern leg has none. Use it to keep an existing legacy
 * deployment (for example a sessionful streamable HTTP wiring) serving 2025
 * traffic next to a strict modern endpoint, now that the entry has no
 * handler-valued `legacy` option:
 *
 * ```ts
 * import { createMcpHandler, isLegacyRequest } from '@modelcontextprotocol/server';
 *
 * const modern = createMcpHandler(factory, { legacy: 'reject' });
 *
 * export default {
 *     async fetch(request: Request): Promise<Response> {
 *         if (await isLegacyRequest(request)) {
 *             // e.g. an existing sessionful WebStandardStreamableHTTPServerTransport wiring
 *             return myExistingLegacyHandler(request);
 *         }
 *         return modern.fetch(request);
 *     }
 * };
 * ```
 *
 * Semantics (identical to the entry's routing):
 *
 * - Returns `true` only for requests with no per-request `_meta` envelope
 *   claim: claim-less POSTs (including the `initialize` handshake and 2025-era
 *   notification POSTs without a modern protocol-version header), body-less
 *   GET/DELETE session operations, all-legacy JSON-RPC batch arrays, posted
 *   JSON-RPC responses, and POSTs whose body is empty or not valid JSON.
 * - Returns `false` for everything the modern path answers, including its
 *   validation-ladder rejections: a request carrying the envelope claim (even
 *   one naming a revision the endpoint does not serve — the modern path
 *   answers it with the unsupported-protocol-version error), a malformed
 *   envelope behind a present claim (answered `-32602`), a request whose
 *   `MCP-Protocol-Version` header names a modern revision but that lacks the
 *   envelope (`-32602`), and header/body mismatches (`-32020`). Consumers
 *   routing on the predicate must send `false` traffic to the modern handler,
 *   never to a legacy handler — the modern path owns those error answers.
 * - `server/discover` probes sent by negotiating clients always carry the
 *   envelope claim, so they are never legacy; a hand-built claim-less POST to
 *   a method named `server/discover` has no claim and classifies legacy,
 *   exactly as the entry itself routes it.
 */
export async function isLegacyRequest(request: Request, parsedBody?: unknown): Promise<boolean> {
    // Classify a clone so the caller's request body stays readable; with a
    // pre-parsed body (or a body-less method) nothing is read and no clone is
    // needed. The predicate never reads forwardRequest, so the classification
    // step's own forwarding clone is skipped.
    const probe = parsedBody === undefined && request.method.toUpperCase() === 'POST' ? request.clone() : request;
    const classified = await classifyEntryRequest(probe, parsedBody, false);
    return classified.step === 'no-json-body' || (classified.step === 'classified' && classified.outcome.kind === 'legacy');
}

/* ------------------------------------------------------------------------ *
 * The entry
 * ------------------------------------------------------------------------ */

/**
 * Creates an HTTP handler that serves the 2026-07-28 protocol revision from a
 * per-request server factory and, by default, falls back to old-school
 * stateless serving for 2025-era traffic. Pass `legacy: 'reject'` for a
 * modern-only strict endpoint.
 *
 * Mounting: `handler.fetch` is the web-standard face (Cloudflare Workers,
 * Deno, Bun, Hono's `c.req.raw`); for Express/Fastify/plain `node:http`, wrap
 * the handler once with `toNodeHandler(handler)` from
 * `@modelcontextprotocol/node`. When mounting bare on a fetch-native runtime,
 * put Origin/Host validation in front of the handler — the entry itself is
 * deliberately validation-free:
 *
 * ```ts
 * import { hostHeaderValidationResponse, originValidationResponse, localhostAllowedHostnames, localhostAllowedOrigins } from '@modelcontextprotocol/server';
 *
 * export default {
 *     async fetch(request: Request): Promise<Response> {
 *         const rejected =
 *             hostHeaderValidationResponse(request, localhostAllowedHostnames()) ??
 *             originValidationResponse(request, localhostAllowedOrigins());
 *         return rejected ?? handler.fetch(request);
 *     }
 * };
 * ```
 *
 * Use ONE factory for both legs: the same tools/resources/prompts definition
 * backs the modern path and the stateless legacy fallback, so the two eras can
 * never drift apart. To keep an existing legacy deployment (for example a
 * sessionful streamable HTTP wiring) serving 2025 traffic instead of the
 * stateless fallback, route in user land with {@linkcode isLegacyRequest} in
 * front of a strict handler — see that predicate's documentation for the
 * pattern. Power users composing transport-neutral routing can also use the
 * exported building blocks directly: {@linkcode classifyInboundRequest} for
 * the era decision and `PerRequestHTTPServerTransport` for single-exchange
 * serving — such compositions must reject POSTs whose Content-Type media type
 * is not `application/json` (415) before parsing the body, using
 * {@linkcode isJsonContentType}; neither building block performs this
 * validation itself.
 *
 * The entry performs no token verification: `authInfo` given to `fetch` is
 * passed through to handlers and the factory as-is and is never derived from
 * request headers.
 */
export function createMcpHandler(factory: McpServerFactory, options: CreateMcpHandlerOptions = {}): McpHttpHandler {
    const { legacy, onerror, responseMode } = options;

    // Construction-time guard for JavaScript callers passing a handler as the
    // legacy value: the option only selects a posture ('stateless' | 'reject').
    // Failing loudly here beats silently treating the handler as the default.
    if (typeof legacy === 'function') {
        throw new TypeError(
            "The 'legacy' option only accepts 'stateless' or 'reject', not a handler function. To serve 2025-era traffic with your own " +
                "handler, route in user land with the exported isLegacyRequest(request) predicate in front of a strict (legacy: 'reject') handler."
        );
    }

    /** Modern per-request instances with an exchange still in flight (close() tears these down). */
    const inflight = new Set<Server>();
    let closed = false;

    const reportError = (error: Error) => {
        try {
            onerror?.(error);
        } catch {
            // Reporting must never alter the response.
        }
    };

    const bus: ServerEventBus = options.bus ?? new InMemoryServerEventBus(reportError);
    const notify = createServerNotifier(bus);
    const listenRouter = createListenRouter({
        bus,
        maxSubscriptions: options.maxSubscriptions ?? DEFAULT_MAX_SUBSCRIPTIONS,
        keepAliveMs: options.keepAliveMs ?? DEFAULT_SSE_KEEP_ALIVE_MS,
        onerror: reportError
    });
    if (responseMode === 'json') {
        // eslint-disable-next-line no-console
        console.warn(
            "responseMode: 'json' drops mid-call notifications. subscriptions/listen streams are always served over SSE regardless; " +
                'other notifications emitted before a result are dropped.'
        );
    }

    // The default posture is the stateless fallback; 'reject' is the only way
    // to turn legacy serving off (modern-only strict).
    const legacyHandler: LegacyHttpHandler | undefined =
        legacy === 'reject' ? undefined : createLegacyStatelessFallback(factory, reportError, options.keepAliveMs);

    async function serveModern(route: InboundModernRoute, request: Request, authInfo: AuthInfo | undefined): Promise<Response> {
        const claimedRevision = route.classification.revision;
        if (claimedRevision === undefined || !SUPPORTED_MODERN_PROTOCOL_VERSIONS.includes(claimedRevision)) {
            // The claim names a revision this endpoint does not serve (an
            // unknown future revision, or a 2025-era revision delivered via the
            // envelope mechanism).
            const error = new UnsupportedProtocolVersionError({
                supported: [...SUPPORTED_MODERN_PROTOCOL_VERSIONS],
                requested: claimedRevision ?? 'unknown'
            });
            reportError(error);
            return jsonRpcErrorResponse(400, error.code, error.message, error.data, echoableRequestId(route.message));
        }

        // SEP-2243 standard-header presence and `Mcp-Name` cross-check
        // (`standard-header-validation` rung; the `MCP-Protocol-Version` and
        // `Mcp-Method` *mismatch* cells are already answered inside
        // `classifyInboundRequest` on the edge `era-classification` rung).
        // Evaluated after the supported-revision
        // gate so an envelope naming a revision this endpoint does not serve
        // is still answered with `-32022` (the supported list is the more
        // useful answer to a client speaking the wrong revision); evaluated
        // before the capability gate, the factory call, and the
        // `Mcp-Param-*` rung so a request that fails several rungs is
        // answered by the standard-header rung first.
        const stdHeaderRejection = validateStandardRequestHeaders(
            {
                httpMethod: request.method,
                mcpMethodHeader: request.headers.get('mcp-method') ?? undefined,
                mcpNameHeader: request.headers.get('mcp-name') ?? undefined
            },
            route
        );
        if (stdHeaderRejection !== undefined) {
            reportError(new Error(`Rejected inbound request (${stdHeaderRejection.cell}): ${stdHeaderRejection.message}`));
            return rejectionResponse(stdHeaderRejection, echoableRequestId(route.message));
        }

        const meta = route.messageKind === 'request' ? requestMetaOf(route.message.params) : undefined;
        const declaredClientCapabilities = meta?.[CLIENT_CAPABILITIES_META_KEY] as ClientCapabilities | undefined;

        // Pre-dispatch capability gate: a request to a method whose processing
        // structurally requires a client capability the request's validated
        // envelope did not declare is refused here, before any instance is
        // constructed or dispatched. Answering at the entry short-circuits
        // before factory construction and pins the spec-mandated HTTP 400 for
        // this error unconditionally; a handler-time -32021 (the
        // input_required gate) also maps to 400 at the per-request transport,
        // but only while no response has been committed.
        if (route.messageKind === 'request') {
            const required = requiredClientCapabilitiesForRequest(route.message.method);
            if (required !== undefined) {
                const missing = missingClientCapabilities(required, declaredClientCapabilities);
                if (missing !== undefined) {
                    const error = new MissingRequiredClientCapabilityError({ requiredCapabilities: missing });
                    reportError(error);
                    return jsonRpcErrorResponse(
                        httpStatusForErrorCode(error.code, 'ladder'),
                        error.code,
                        error.message,
                        error.data,
                        route.message.id
                    );
                }
            }
        }

        const product = await factory({
            era: 'modern',
            ...(authInfo !== undefined && { authInfo }),
            requestInfo: request
        });
        const server = product instanceof McpServer ? product.server : product;

        // Entry-handled `subscriptions/listen`: the router owns ack-first /
        // per-stream filtering / subscription-id stamping / keepalive /
        // capacity / teardown. The factory IS constructed for listen — to read
        // the instance's declared capabilities only, so the acknowledged
        // filter reflects what the server can actually deliver. Unlike the
        // discover path (which connects via the per-request transport and tears
        // down with it), the probe instance is never connected: capabilities
        // are read off the unconnected instance and it is closed immediately.
        // Authorization the consumer performs inside the factory therefore DOES
        // see listen requests, although token verification still belongs at the
        // middleware layer mounted in front of this entry.
        if (route.messageKind === 'request' && route.message.method === 'subscriptions/listen') {
            const capabilities = server.getCapabilities();
            const serverInfo = serverIdentityOf(server);
            void product.close().catch(reportError);
            return listenRouter.serve(route.message, request.signal, capabilities, serverInfo);
        }

        // SEP-2243 `Mcp-Param-*` server-side validation (pre-dispatch ladder
        // rung): for a `tools/call`, look up the named tool's JSON inputSchema
        // on the just-produced instance and compare every `x-mcp-header`
        // declaration against the request's `Mcp-Param-{Name}` headers and the
        // body `arguments`. A mismatch (or a missing header for a present body
        // value, or an invalid Base64 sentinel) emits the same `400` /
        // `-32020` (`HeaderMismatch`) shape the edge cross-checks use. Only
        // applied when the factory returns an `McpServer` (the registry is the
        // schema source); a low-level `Server` factory has no registry, so
        // there is nothing to validate against.
        if (route.messageKind === 'request' && route.message.method === 'tools/call' && product instanceof McpServer) {
            const callParams = route.message.params as { name?: string; arguments?: Record<string, unknown> } | undefined;
            const toolName = typeof callParams?.name === 'string' ? callParams.name : undefined;
            const inputSchema = toolName === undefined ? undefined : product.toolInputSchemaJson(toolName);
            if (inputSchema !== undefined) {
                const scan = scanXMcpHeaderDeclarations(inputSchema);
                if (scan.valid && scan.declarations.length > 0) {
                    const rejection = validateMcpParamHeaders(scan.declarations, callParams?.arguments, request.headers);
                    if (rejection !== undefined) {
                        void product.close().catch(reportError);
                        reportError(new Error(`Rejected inbound request (${rejection.cell}): ${rejection.message}`));
                        return rejectionResponse(rejection, route.message.id);
                    }
                }
            }
        }

        // Era-write at instance binding, then modern-only handler installation —
        // both before the instance is connected to the per-request transport.
        setNegotiatedProtocolVersion(server, claimedRevision);
        installModernOnlyHandlers(server, SUPPORTED_MODERN_PROTOCOL_VERSIONS);

        if (meta !== undefined) {
            seedClientIdentityFromEnvelope(server, {
                clientInfo: meta[CLIENT_INFO_META_KEY] as Implementation | undefined,
                clientCapabilities: declaredClientCapabilities
            });
        }

        // Track the instance until its exchange tears down so close() can abort it.
        const previousOnClose = server.onclose;
        inflight.add(server);
        server.onclose = () => {
            inflight.delete(server);
            previousOnClose?.();
        };

        try {
            const response = await invoke(product, route.message, {
                classification: route.classification,
                request,
                ...(authInfo !== undefined && { authInfo }),
                ...(responseMode !== undefined && { responseMode }),
                ...(options.keepAliveMs !== undefined && { keepAliveMs: options.keepAliveMs })
            });
            if (route.messageKind === 'notification') {
                // Notification exchanges have no terminal response to ride the
                // transport's auto-close, so release the per-request instance here.
                queueMicrotask(() => void server.close().catch(() => {}));
            }
            return response;
        } catch (error) {
            if (error instanceof SdkError && error.code === SdkErrorCode.ConnectionClosed) {
                // The client went away before a response existed; there is
                // nobody left to answer.
                return new Response(null, { status: 499 });
            }
            // No terminal response will ride the transport's close chain after a
            // failure here: close the per-request instance explicitly and drop it
            // from the in-flight set so repeated failures cannot accumulate
            // connected instances until handler.close().
            await server.close().catch(() => {});
            inflight.delete(server);
            reportError(toError(error));
            return internalServerErrorResponse(echoableRequestId(route.message));
        }
    }

    async function serveLegacyRoute(
        route: InboundLegacyRoute,
        forwardRequest: Request,
        authInfo: AuthInfo | undefined,
        parsedBody: unknown
    ): Promise<Response> {
        if (legacyHandler !== undefined) {
            return legacyHandler(forwardRequest, {
                ...(authInfo !== undefined && { authInfo }),
                ...(parsedBody !== undefined && { parsedBody })
            });
        }
        const strict = modernOnlyStrictRejection(route, SUPPORTED_MODERN_PROTOCOL_VERSIONS);
        if (strict === undefined) {
            // Legacy-classified notification on a modern-only endpoint:
            // acknowledged and dropped, never dispatched.
            return new Response(null, { status: 202 });
        }
        reportError(new Error(`Rejected 2025-era request on a modern-only endpoint (${strict.cell}): ${strict.message}`));
        return rejectionResponse(strict, echoableRequestId(parsedBody));
    }

    async function handle(request: Request, requestOptions?: McpHandlerRequestOptions): Promise<Response> {
        const authInfo = requestOptions?.authInfo;

        // Content-Type check, answered before the body is read (parsed media
        // type — see isJsonContentType). Load-bearing for the modern leg,
        // whose ladder does not inspect Content-Type; the legacy transport
        // keeps its own check for hand-wired use, so via this entry a
        // doubly-invalid request answers 415 here before the transport's 406
        // Accept check would.
        if (request.method.toUpperCase() === 'POST' && !isJsonContentType(request.headers.get('content-type'))) {
            reportError(new Error('Unsupported Media Type: Content-Type must be application/json'));
            return jsonRpcErrorResponse(415, -32_000, 'Unsupported Media Type: Content-Type must be application/json');
        }

        const classified = await classifyEntryRequest(request, requestOptions?.parsedBody);

        if (classified.step === 'unreadable-body') {
            return jsonRpcErrorResponse(400, -32_700, 'Parse error: the request body could not be read');
        }
        if (classified.step === 'no-json-body') {
            // No JSON body to classify: there is no envelope claim, so this is
            // legacy traffic when legacy serving is configured (the legacy leg
            // answers its own parse error, unchanged), and a parse error
            // otherwise.
            if (legacyHandler !== undefined) {
                return legacyHandler(classified.forwardRequest, { ...(authInfo !== undefined && { authInfo }) });
            }
            return jsonRpcErrorResponse(400, -32_700, 'Parse error: the request body is not valid JSON');
        }

        const { outcome, body, parsedBody, forwardRequest } = classified;
        try {
            switch (outcome.kind) {
                case 'reject': {
                    reportError(new Error(`Rejected inbound request (${outcome.cell}): ${outcome.message}`));
                    return rejectionResponse(outcome, echoableRequestId(body));
                }
                case 'modern': {
                    return await serveModern(outcome, request, authInfo);
                }
                case 'legacy': {
                    return await serveLegacyRoute(outcome, forwardRequest, authInfo, parsedBody);
                }
            }
        } catch (error) {
            // Entry-internal failure while serving a classified request (a
            // throwing factory or a failed connect, on either leg): the parsed
            // body is in scope here, so the 500 body echoes the request id when
            // it could be read.
            reportError(toError(error));
            return internalServerErrorResponse(echoableRequestId(body));
        }
    }

    const fetchFace = async (request: Request, requestOptions?: McpHandlerRequestOptions): Promise<Response> => {
        if (closed) {
            throw new Error('This MCP handler has been closed');
        }
        try {
            return await handle(request, requestOptions);
        } catch (error) {
            reportError(toError(error));
            return internalServerErrorResponse(echoableRequestId(requestOptions?.parsedBody));
        }
    };

    return {
        fetch: fetchFace,
        notify,
        bus,
        close: async () => {
            closed = true;
            listenRouter.closeAll();
            const closing = [...inflight].map(server => server.close().catch(() => {}));
            inflight.clear();
            await Promise.all(closing);
