 * ```ts source="./oauthMetadata.examples.ts#oauthMetadataResponse_fetchHandler"
 * async function fetchHandler(request: Request): Promise<Response> {
 *     return oauthMetadataResponse(request, options) ?? serveMcp(request);
 * }
 * ```
