import type { StandardSchemaV1 } from '@modelcontextprotocol/core-internal';

export const COMPLETABLE_SYMBOL: unique symbol = Symbol.for('mcp.completable');

export type CompleteCallback<T extends StandardSchemaV1 = StandardSchemaV1> = (
    value: StandardSchemaV1.InferInput<T>,
    context?: {
        arguments?: Record<string, string>;
    }
) => StandardSchemaV1.InferInput<T>[] | Promise<StandardSchemaV1.InferInput<T>[]>;

export type CompletableMeta<T extends StandardSchemaV1 = StandardSchemaV1> = {
    complete: CompleteCallback<T>;
};

export type CompletableSchema<T extends StandardSchemaV1> = T & {
    [COMPLETABLE_SYMBOL]: CompletableMeta<T>;
};

/**
 * Wraps a schema to provide autocompletion capabilities. Useful for, e.g., prompt arguments in MCP.
 *
 * @example
 * ```ts source="./completable.examples.ts#completable_basicUsage"
 * server.registerPrompt(
 *     'review-code',
 *     {
 *         title: 'Code Review',
 *         argsSchema: z.object({
 *             language: completable(z.string().describe('Programming language'), value =>
 *                 ['typescript', 'javascript', 'python', 'rust', 'go'].filter(lang => lang.startsWith(value))
 *             )
 *         })
 *     },
 *     ({ language }) => ({
 *         messages: [
 *             {
 *                 role: 'user' as const,
 *                 content: {
 *                     type: 'text' as const,
 *                     text: `Review this ${language} code.`
 *                 }
 *             }
 *         ]
 *     })
 * );
 * ```
 *
 * @see {@linkcode server/mcp.McpServer.registerPrompt | McpServer.registerPrompt} for using completable schemas in prompt argument definitions
 */
export function completable<T extends StandardSchemaV1>(schema: T, complete: CompleteCallback<T>): CompletableSchema<T> {
    Object.defineProperty(schema as object, COMPLETABLE_SYMBOL, {
        value: { complete } as CompletableMeta<T>,
        enumerable: false,
        writable: false,
        configurable: false
    });
    return schema as CompletableSchema<T>;
}

/**
 * Checks if a schema is completable (has completion metadata).
 */
export function isCompletable(schema: unknown): schema is CompletableSchema<StandardSchemaV1> {
    return !!schema && typeof schema === 'object' && COMPLETABLE_SYMBOL in (schema as object);
}

/**
 * Gets the completer callback from a completable schema, if it exists.
 */
export function getCompleter<T extends StandardSchemaV1>(schema: T): CompleteCallback<T> | undefined {
    const meta = (schema as unknown as { [COMPLETABLE_SYMBOL]?: CompletableMeta<T> })[COMPLETABLE_SYMBOL];
    return meta?.complete as CompleteCallback<T> | undefined;
}
/** Default interval between SSE keep-alive comment frames. */
export const DEFAULT_SSE_KEEP_ALIVE_MS = 15_000;

const MAX_TIMER_DELAY_MS = 2 ** 31 - 1;

/** Arms an unref'd timer, or disables keep-alive for invalid delays. */
export function armSseKeepAlive(intervalMs: number, onTick: () => void): ReturnType<typeof setInterval> | undefined {
    if (!Number.isFinite(intervalMs) || intervalMs < 1) {
        return undefined;
    }

    const timer = setInterval(onTick, Math.min(intervalMs, MAX_TIMER_DELAY_MS));
    (timer as { unref?: () => void }).unref?.();
    return timer;
}
import type { ServerCapabilities, SubscriptionFilter } from '@modelcontextprotocol/core-internal';

/**
 * A change event a server publishes for delivery on open `subscriptions/listen`
 * streams. Each variant maps onto exactly one notification method:
 *
 * - `tools_list_changed` → `notifications/tools/list_changed`
 * - `prompts_list_changed` → `notifications/prompts/list_changed`
 * - `resources_list_changed` → `notifications/resources/list_changed`
 * - `resource_updated` → `notifications/resources/updated` (carries the URI)
 *
 * The bus carries the EVENT, not the wire shape — the entry's listen router
 * owns subscription-id stamping and per-stream filtering.
 */
export type ServerEvent =
    | { kind: 'tools_list_changed' }
    | { kind: 'prompts_list_changed' }
    | { kind: 'resources_list_changed' }
    | { kind: 'resource_updated'; uri: string };

/**
 * The server-side change-event seam for `subscriptions/listen`.
 *
 * The serving entry (`createMcpHandler`) owns the per-stream listen router:
 * each open `subscriptions/listen` stream registers a listener via
 * `subscribe()`, and consumer code (typically via `handler.notify.*` sugar)
 * publishes change events via `publish()`. In-process servers can use the
 * default {@linkcode InMemoryServerEventBus}; multi-process deployments
 * implement this interface over their own pub/sub.
 *
 * The SDK owns wire semantics (ack-first, filtering, subscription-id
 * stamping, teardown); a `ServerEventBus` only sources the events. It MUST
 * NOT echo back to the listener that published an event when called from
 * inside that listener (no surprise here — the default delivers
 * synchronously and listeners never publish).
 */
export interface ServerEventBus {
    /**
     * Publish a change event to every registered listener.
     */
    publish(event: ServerEvent): void;
    /**
     * Register a listener; returns an idempotent unsubscribe function.
     */
    subscribe(listener: (event: ServerEvent) => void): () => void;
}

/**
 * A `ServerEventBus` backed by an in-process listener set.
 *
 * `publish()` delivers synchronously to the live listener set (a listener
 * unsubscribing itself mid-dispatch is safe; the entry's listen-router
 * listeners never unsubscribe peers). A throwing listener does not stop
 * delivery to the others.
 */
export class InMemoryServerEventBus implements ServerEventBus {
    private readonly _listeners = new Set<(event: ServerEvent) => void>();

    /**
     * @param onerror - Optional callback for errors thrown by listeners
     *   during dispatch.
     */
    constructor(private readonly onerror?: (error: Error) => void) {}

    publish(event: ServerEvent): void {
        for (const listener of this._listeners) {
            try {
                listener(event);
            } catch (error) {
                this.onerror?.(error instanceof Error ? error : new Error(String(error)));
            }
        }
    }

    subscribe(listener: (event: ServerEvent) => void): () => void {
        this._listeners.add(listener);
        let live = true;
        return () => {
            if (!live) return;
            live = false;
            this._listeners.delete(listener);
        };
    }

    /** The number of currently registered listeners (test/introspection only — the routers track capacity via their own open-subscription set). */
    get listenerCount(): number {
        return this._listeners.size;
    }
}

/**
 * Typed publish-side facade over `bus.publish` returned by `createMcpHandler`:
 * each method publishes the corresponding {@linkcode ServerEvent}. Prefer this
 * over calling `bus.publish` directly — the names match the wire methods.
 */
export interface ServerNotifier {
    /** Publish `notifications/tools/list_changed` to every open subscription that opted in. */
    toolsChanged(): void;
    /** Publish `notifications/prompts/list_changed` to every open subscription that opted in. */
    promptsChanged(): void;
    /** Publish `notifications/resources/list_changed` to every open subscription that opted in. */
    resourcesChanged(): void;
    /** Publish `notifications/resources/updated` for `uri` to every open subscription that opted in to that URI. */
    resourceUpdated(uri: string): void;
}

/** Build a {@linkcode ServerNotifier} over a bus. */
export function createServerNotifier(bus: ServerEventBus): ServerNotifier {
    return {
        toolsChanged: () => bus.publish({ kind: 'tools_list_changed' }),
        promptsChanged: () => bus.publish({ kind: 'prompts_list_changed' }),
        resourcesChanged: () => bus.publish({ kind: 'resources_list_changed' }),
        resourceUpdated: (uri: string) => bus.publish({ kind: 'resource_updated', uri })
    };
}

/**
 * Whether a `subscriptions/listen` filter accepts a given change event.
 *
 * Pure: no I/O, no mutation. The filter governs ONLY the four
 * subscription-gated change types — non-gated notifications never reach the
 * bus and are not modeled here.
 *
 * `resource_updated` matches only when `resourceSubscriptions` is present and
 * contains the event's URI exactly (per the spec: "for these resource URIs").
 */
export function listenFilterAccepts(filter: SubscriptionFilter, event: ServerEvent): boolean {
    switch (event.kind) {
        case 'tools_list_changed': {
            return filter.toolsListChanged === true;
        }
        case 'prompts_list_changed': {
            return filter.promptsListChanged === true;
        }
        case 'resources_list_changed': {
            return filter.resourcesListChanged === true;
        }
        case 'resource_updated': {
            return filter.resourceSubscriptions !== undefined && filter.resourceSubscriptions.includes(event.uri);
        }
    }
}

/**
 * The honored subset of a requested filter: keeps only the fields the client
 * explicitly opted in to (drops `false` and absent fields), narrowed against
 * the server's declared capabilities when supplied. The serving entry sends
 * this back in `notifications/subscriptions/acknowledged` so the ack reflects
 * what the server can actually deliver.
 *
 * - `toolsListChanged` is honored only when `capabilities.tools.listChanged`
 *   is advertised; likewise `promptsListChanged` / `resourcesListChanged`.
 * - `resourceSubscriptions` is honored only when
 *   `capabilities.resources.subscribe` is advertised.
 *
 * `capabilities` is optional on this pure helper for test convenience only —
 * both wired routers REQUIRE capabilities at the call site (the HTTP router's
 * `serve()` takes a required parameter; `StdioListenRouter.serve()` throws
 * before `setServerCapabilities()` was called), so the fail-open
 * `undefined → honor everything` branch is never reachable on a wired entry.
 */
export function honoredSubset(requested: SubscriptionFilter, capabilities?: ServerCapabilities): SubscriptionFilter {
    const honored: SubscriptionFilter = {};
    const allow = (bit: unknown): boolean => capabilities === undefined || bit === true;
    if (requested.toolsListChanged === true && allow(capabilities?.tools?.listChanged)) honored.toolsListChanged = true;
    if (requested.promptsListChanged === true && allow(capabilities?.prompts?.listChanged)) honored.promptsListChanged = true;
    if (requested.resourcesListChanged === true && allow(capabilities?.resources?.listChanged)) honored.resourcesListChanged = true;
    if (
        requested.resourceSubscriptions !== undefined &&
        requested.resourceSubscriptions.length > 0 &&
        allow(capabilities?.resources?.subscribe)
    ) {
        honored.resourceSubscriptions = [...requested.resourceSubscriptions];
    }
    return honored;
}

/** Map a {@linkcode ServerEvent} onto its wire notification `{method, params}`. */
export function serverEventToNotification(event: ServerEvent): { method: string; params?: { uri: string } } {
    switch (event.kind) {
        case 'tools_list_changed': {
            return { method: 'notifications/tools/list_changed' };
        }
        case 'prompts_list_changed': {
            return { method: 'notifications/prompts/list_changed' };
        }
        case 'resources_list_changed': {
            return { method: 'notifications/resources/list_changed' };
        }
        case 'resource_updated': {
            return { method: 'notifications/resources/updated', params: { uri: event.uri } };
        }
    }
}
/**
 * The entry-handled `subscriptions/listen` router for the HTTP serving entry.
 *
 * `createMcpHandler` recognizes a modern-classified `subscriptions/listen`
 * request and routes it here: the entry owns ack-first, per-stream filtering,
 * subscription-id stamping, keepalive, capacity guarding, and teardown. The
 * consumer's factory IS constructed for listen, to read the instance's
 * declared `ServerCapabilities` only — the probe instance is never connected
 * and is closed immediately after the capabilities read. Token verification
 * and any per-request authorization still belong at the middleware layer
 * mounted in front of `createMcpHandler` (the entry's documented authz
 * posture).
 *
 * Per the spec at protocol revision 2026-07-28:
 * - The acknowledged notification is the FIRST message on the stream and
 *   carries the honored subset of the requested filter.
 * - Every notification on the stream (including the ack) carries the listen
 *   request's JSON-RPC id under `_meta['io.modelcontextprotocol/subscriptionId']`.
 * - The server MUST NOT deliver a notification type the client did not request.
 * - Server-side graceful close (`closeAll()`) emits the empty
 *   `subscriptions/listen` JSON-RPC result (the `SubscriptionsListenResult` —
 *   `_meta` carries the subscription id) before closing the stream; an abrupt
 *   transport close carries no response and the client treats it as a
 *   disconnect.
 */
import type {
    Implementation,
    JSONRPCRequest,
    RequestId,
    ServerCapabilities,
    SubscriptionFilter
} from '@modelcontextprotocol/core-internal';
import { codecForVersion, MODERN_WIRE_REVISION, SERVER_INFO_META_KEY, SUBSCRIPTION_ID_META_KEY } from '@modelcontextprotocol/core-internal';

import type { ServerEventBus } from './serverEventBus';
import { honoredSubset, listenFilterAccepts, serverEventToNotification } from './serverEventBus';
import { armSseKeepAlive, DEFAULT_SSE_KEEP_ALIVE_MS } from './sseKeepAlive';

/** Default capacity guard: refuse a new subscription when this many are already open. */
export const DEFAULT_MAX_SUBSCRIPTIONS = 1024;

/** Options for {@linkcode createListenRouter}. */
export interface ListenRouterOptions {
    /** The event bus listen streams subscribe to. */
    bus: ServerEventBus;
    /** Reject a new listen with `-32603` when this many subscriptions are already open (default 1024). */
    maxSubscriptions?: number;
    /** SSE comment-frame keepalive interval; `0` disables keepalive (default 15000). */
    keepAliveMs?: number;
    /** Out-of-band error reporting (never alters the response). */
    onerror?: (error: Error) => void;
}

/**
 * A wire-shape notification body (method + loose params).
 * @internal
 */
export interface NotificationBody {
    method: string;
    params: { _meta?: Record<string, unknown>; [key: string]: unknown };
}

function jsonRpcError(id: RequestId | null, code: number, message: string): Response {
    return Response.json({ jsonrpc: '2.0', error: { code, message }, id }, { status: 200 });
}

/** Stamp the subscription id onto a notification's `_meta`. Non-mutating. */
function stampSubscriptionId(
    notification: { method: string; params?: { _meta?: Record<string, unknown>; [key: string]: unknown } },
    subscriptionId: RequestId
): NotificationBody {
    return {
        method: notification.method,
        params: {
            ...notification.params,
            _meta: { ...notification.params?._meta, [SUBSCRIPTION_ID_META_KEY]: subscriptionId }
        }
    };
}

/**
 * Read the requested filter off a `subscriptions/listen` request body.
 * Returns the validated filter, or `undefined` when `params.notifications`
 * is absent or fails the schema (the caller answers `-32602` — the spec
 * marks `notifications` REQUIRED on the listen request).
 */
export function parseListenFilter(message: JSONRPCRequest): SubscriptionFilter | undefined {
    // `subscriptions/listen` is 2026-only vocabulary; route through the era
    // codec's request validator (the wire layer owns the filter schema).
    const outcome = codecForVersion(MODERN_WIRE_REVISION).validateRequest('subscriptions/listen', message);
    return outcome.ok ? outcome.value.params?.notifications : undefined;
}

/**
 * The HTTP listen router: holds the set of open subscriptions and serves
 * each listen request as an SSE response.
 */
export interface ListenRouter {
    /**
     * Serve one `subscriptions/listen` request and return the SSE `Response`
     * (or, on capacity / params rejection, the in-band JSON-RPC error
     * `Response`). The ack notification is the first SSE frame.
     *
     * `capabilities` is required: the acknowledged filter is always narrowed
     * against what the serving instance advertises (honoring a filter without
     * capabilities would fail open and deliver unadvertised types).
     * `serverInfo` is the serving instance's identity, stamped onto the
     * graceful-close result's `_meta` (the spec's `SubscriptionsListenResultMeta`
     * extends `ResultMetaObject`, so the serverInfo SHOULD applies there too).
     */
    serve(message: JSONRPCRequest, signal: AbortSignal | undefined, capabilities: ServerCapabilities, serverInfo: Implementation): Response;
    /**
     * Gracefully close every open subscription stream: emits the empty
     * `subscriptions/listen` JSON-RPC result (the spec's graceful-close
     * signal) as the final SSE frame, then closes the stream.
     */
    closeAll(): void;
    /** The number of currently open subscription streams (for tests / introspection). */
    readonly openCount: number;
}

export function createListenRouter(options: ListenRouterOptions): ListenRouter {
    const { bus, onerror } = options;
    const maxSubscriptions = options.maxSubscriptions ?? DEFAULT_MAX_SUBSCRIPTIONS;
    const keepAliveMs = options.keepAliveMs ?? DEFAULT_SSE_KEEP_ALIVE_MS;

    const open = new Set<(graceful: boolean) => void>();

    function serve(
        message: JSONRPCRequest,
        signal: AbortSignal | undefined,
        capabilities: ServerCapabilities,
        serverInfo: Implementation
    ): Response {
        // Capacity guard, pre-ack: in-band -32603 on HTTP 200.
        if (open.size >= maxSubscriptions) {
            onerror?.(new Error(`subscriptions/listen refused: subscription limit reached (${maxSubscriptions})`));
            return jsonRpcError(message.id, -32_603, 'Subscription limit reached');
        }
        const filter = parseListenFilter(message);
        if (filter === undefined) {
            return jsonRpcError(message.id, -32_602, "Invalid params: 'notifications' is required and must be a valid SubscriptionFilter");
        }
        const honored = honoredSubset(filter, capabilities);
        // The spec carries the listen request's JSON-RPC id verbatim as the
        // subscription id; demux is per-connection (each HTTP listen has its
        // own SSE stream) so client-chosen ids cannot route across requests.
        const subscriptionId = message.id;

        const encoder = new TextEncoder();
        let controller!: ReadableStreamDefaultController<Uint8Array>;
        let closed = false;
        let unsubscribe: (() => void) | undefined;
        let keepAliveTimer: ReturnType<typeof setInterval> | undefined;
        let abortCleanup: (() => void) | undefined;

        const writeFrame = (frame: string) => {
            if (closed) return;
            try {
                controller.enqueue(encoder.encode(frame));
            } catch (error) {
                onerror?.(error instanceof Error ? error : new Error(String(error)));
            }
        };
        const writeNotification = (method: string, params: { _meta?: Record<string, unknown>; [key: string]: unknown }) => {
            writeFrame(`event: message\ndata: ${JSON.stringify({ jsonrpc: '2.0', method, params })}\n\n`);
        };

        const teardown = (graceful: boolean) => {
            if (closed) return;
            if (graceful) {
                // Server-side graceful close: emit the empty
                // `subscriptions/listen` JSON-RPC result before closing the
                // stream so the client distinguishes graceful end from a
                // transport drop. Written before `closed = true` so writeFrame
                // still enqueues.
                writeFrame(
                    `event: message\ndata: ${JSON.stringify({
                        jsonrpc: '2.0',
                        id: subscriptionId,
                        result: {
                            resultType: 'complete',
                            _meta: { [SUBSCRIPTION_ID_META_KEY]: subscriptionId, [SERVER_INFO_META_KEY]: serverInfo }
                        }
                    })}\n\n`
                );
            }
            closed = true;
            try {
                unsubscribe?.();
            } catch (error) {
                onerror?.(error instanceof Error ? error : new Error(String(error)));
            }
            if (keepAliveTimer !== undefined) clearInterval(keepAliveTimer);
            abortCleanup?.();
            open.delete(teardown);
            try {
                controller.close();
            } catch {
                // Already closed/cancelled by the consumer.
            }
        };

        const readable = new ReadableStream<Uint8Array>({
            start(streamController) {
                controller = streamController;

                // Ack-first MUST: the acknowledged notification is the first
                // frame on the stream, stamped with the subscription id.
                const ack = stampSubscriptionId(
                    { method: 'notifications/subscriptions/acknowledged', params: { notifications: honored } },
                    subscriptionId
                );
                writeNotification(ack.method, ack.params);

                // Only after the ack frame is enqueued does delivery activate.
                unsubscribe = bus.subscribe(event => {
                    if (closed || !listenFilterAccepts(honored, event)) return;
                    const note = stampSubscriptionId(serverEventToNotification(event), subscriptionId);
                    writeNotification(note.method, note.params);
                });

                keepAliveTimer = armSseKeepAlive(keepAliveMs, () => writeFrame(': keepalive\n\n'));

                open.add(teardown);
            },
            cancel() {
                // The client closed the SSE stream — the spec's HTTP cancel
                // signal. Not a server-side graceful close, so no listen
                // result is written (and the consumer is gone anyway).
                teardown(false);
            }
        });

        if (signal !== undefined) {
            if (signal.aborted) {
                teardown(false);
            } else {
                const onAbort = () => teardown(false);
                signal.addEventListener('abort', onAbort, { once: true });
                abortCleanup = () => signal.removeEventListener('abort', onAbort);
            }
        }

        return new Response(readable, {
            status: 200,
            headers: {
                'Content-Type': 'text/event-stream',
                'Cache-Control': 'no-cache, no-transform',
                Connection: 'keep-alive',
                'X-Accel-Buffering': 'no'
            }
        });
    }

    return {
        serve,
        closeAll() {
            for (const teardown of open) teardown(true);
        },
        get openCount() {
            return open.size;
        }
    };
}

/* ------------------------------------------------------------------------ *
 * Stdio listen router
 * ------------------------------------------------------------------------ */

/** A graceful-close `subscriptions/listen` result frame emitted by {@linkcode StdioListenRouter.teardownAll}. */
export interface ListenCloseFrame {
    jsonrpc: '2.0';
    id: RequestId;
    result: {
        resultType: 'complete';
        _meta: { [SUBSCRIPTION_ID_META_KEY]: RequestId; [SERVER_INFO_META_KEY]?: Implementation };
    };
}

const CHANGE_NOTIFICATION_METHODS: ReadonlySet<string> = new Set([
    'notifications/tools/list_changed',
    'notifications/prompts/list_changed',
    'notifications/resources/list_changed',
    'notifications/resources/updated'
]);

/**
 * Per-connection listen state for the stdio entry. One instance is held by
 * `serveStdio` for the connection lifetime; it routes inbound
 * `subscriptions/listen` / `notifications/cancelled` and rewrites outbound
 * change notifications onto the active subscriptions. No bus — the long-lived
 * pinned instance's existing `send*ListChanged()` calls feed straight into
 * `routeOutbound()`.
 */
export class StdioListenRouter {
    /** Active subscriptions, keyed by the listen request's JSON-RPC id verbatim. */
    private readonly _subs = new Map<RequestId, SubscriptionFilter>();
    /**
     * The serving instance's declared capabilities. Filled in by the entry
     * once the modern instance is constructed (the router is created before
     * the instance exists), so the acknowledged filter is narrowed against
     * what the server can actually deliver.
     */
    private _serverCapabilities: ServerCapabilities | undefined;
    /**
     * The serving instance's identity, stamped onto the graceful-close
     * results' `_meta` (the spec's `SubscriptionsListenResultMeta` extends
     * `ResultMetaObject`). Handed over together with the capabilities.
     */
    private _serverInfo: Implementation | undefined;

    constructor(
        private readonly _maxSubscriptions: number = DEFAULT_MAX_SUBSCRIPTIONS,
        serverCapabilities?: ServerCapabilities,
        serverInfo?: Implementation
    ) {
        this._serverCapabilities = serverCapabilities;
        this._serverInfo = serverInfo;
    }

    /**
     * Record the serving instance's declared capabilities and identity once
     * it has been constructed. Called by `serveStdio`'s connect path;
     * subsequent `serve()` calls narrow the honored filter against the
     * capabilities, and `teardownAll()` stamps the identity.
     */
    setServerCapabilities(capabilities: ServerCapabilities, serverInfo?: Implementation): void {
        this._serverCapabilities = capabilities;
        if (serverInfo !== undefined) this._serverInfo = serverInfo;
    }

    /** Whether `id` is an active listen subscription on this connection. */
    has(id: RequestId): boolean {
        return this._subs.has(id);
    }

    /**
     * Serve one inbound `subscriptions/listen` request: registers the
     * subscription and returns the stamped acknowledged notification (or, on
     * capacity / params rejection, the in-band JSON-RPC error response).
     *
     * @throws when called before {@linkcode setServerCapabilities} (or the
     * constructor) has supplied the serving instance's capabilities. Honoring a
     * filter without knowing the server's advertised capabilities would fail
     * open (deliver unadvertised types); the entry guarantees capabilities are
     * set before any listen request is routed here.
     */
    serve(message: JSONRPCRequest): NotificationBody | { jsonrpc: '2.0'; id: RequestId; error: { code: number; message: string } } {
        if (this._serverCapabilities === undefined) {
            throw new Error(
                'StdioListenRouter.serve() called before setServerCapabilities(); refusing to honor a filter without capabilities'
            );
        }
        if (this._subs.size >= this._maxSubscriptions) {
            return { jsonrpc: '2.0', id: message.id, error: { code: -32_603, message: 'Subscription limit reached' } };
        }
        const filter = parseListenFilter(message);
        if (filter === undefined) {
            return {
                jsonrpc: '2.0',
                id: message.id,
                error: { code: -32_602, message: "Invalid params: 'notifications' is required and must be a valid SubscriptionFilter" }
            };
        }
        const honored = honoredSubset(filter, this._serverCapabilities);
        this._subs.set(message.id, honored);
        return stampSubscriptionId({ method: 'notifications/subscriptions/acknowledged', params: { notifications: honored } }, message.id);
    }

    /**
     * Tear down one subscription (inbound `notifications/cancelled`). Returns
     * `true` when a subscription was removed. After this call NOTHING further
     * is delivered for that subscription id (the post-cancel hardening).
     */
    cancel(id: RequestId): boolean {
        return this._subs.delete(id);
    }

    /**
     * Route an outbound notification through the active subscriptions.
     *
     * - For a subscription-gated change notification, returns one stamped copy
     *   per subscription that opted in to it (an empty array means it is
     *   dropped — the modern era never delivers an un-requested change type).
     * - For any other outbound message, returns `'passthrough'` (the entry
     *   forwards it as-is).
     */
    routeOutbound(message: { method: string; params?: { [key: string]: unknown } }): NotificationBody[] | 'passthrough' {
        if (!CHANGE_NOTIFICATION_METHODS.has(message.method)) {
            return 'passthrough';
        }
        const uriParam: unknown = message.params?.['uri'];
        const uri = typeof uriParam === 'string' ? uriParam : undefined;
        const event = notificationToServerEvent(message.method, uri);
        const out: NotificationBody[] = [];
        for (const [subscriptionId, filter] of this._subs) {
            if (listenFilterAccepts(filter, event)) {
                out.push(stampSubscriptionId({ method: message.method, params: message.params ?? {} }, subscriptionId));
            }
        }
        return out;
    }

    /**
     * Server-side graceful teardown of every active subscription: returns the
     * empty `subscriptions/listen` JSON-RPC result for each subscription id —
     * the spec's graceful-close signal, `_meta` carrying the subscription id
     * and the serving instance's identity — for the entry to emit before
     * closing the wire. Clears the set so nothing further is delivered.
     */
    teardownAll(): ListenCloseFrame[] {
        const out: ListenCloseFrame[] = [];
        for (const id of this._subs.keys()) {
            out.push({
                jsonrpc: '2.0',
                id,
                result: {
                    resultType: 'complete',
                    _meta: {
                        [SUBSCRIPTION_ID_META_KEY]: id,
                        ...(this._serverInfo !== undefined && { [SERVER_INFO_META_KEY]: this._serverInfo })
                    }
                }
            });
        }
        this._subs.clear();
        return out;
    }
}

function notificationToServerEvent(method: string, uri: string | undefined): import('./serverEventBus').ServerEvent {
    switch (method) {
        case 'notifications/tools/list_changed': {
            return { kind: 'tools_list_changed' };
        }
        case 'notifications/prompts/list_changed': {
            return { kind: 'prompts_list_changed' };
        }
        case 'notifications/resources/list_changed': {
            return { kind: 'resources_list_changed' };
        }
        default: {
            return { kind: 'resource_updated', uri: uri ?? '' };
        }
    }
}
/**
 * The legacy `input_required` shim: serves write-once handlers on 2025-era
 * sessions. `Server` holds one instance and delegates to it from the
 * multi-round-trip seam when a handler returns an input-required result on a
 * 2025-era request: each embedded request goes out as a real server→client
 * request (`elicitation/create` / `sampling/createMessage` / `roots/list`,
 * stamped with the originating request id for stream association), and the
 * handler is re-entered with the collected `inputResponses` until it returns
 * a final result or the round cap is exhausted.
 *
 * Semantics mirror the modern client driver so a handler cannot tell which
 * era fulfilled it: per-round REPLACED `inputResponses`, byte-exact
 * `requestState` echo (re-verified by the configured hook each round), paced
 * requestState-only rounds. The loop lives inside the originating request's
 * lifetime — nothing is parked, cancellation chains through every leg.
 * Failures surface per family: tools/call → `isError` tool results,
 * prompts/resources → JSON-RPC errors; malformed results fail loudly as
 * server bugs. Package-internal — not exported from the index.
 */
import type {
    ClientCapabilities,
    CreateMessageRequest,
    ElicitRequestFormParams,
    ElicitRequestURLParams,
    JSONRPCRequest,
    RequestOptions,
    Result,
    ServerContext
} from '@modelcontextprotocol/core-internal';
import {
    inputRequiredRoundsExceededMessage,
    isInputRequiredResult,
    linkedRoundAbort,
    missingClientCapabilities,
    ProtocolError,
    ProtocolErrorCode,
    REQUEST_STATE_ONLY_LEG_PACING_MS,
    requestStateAccessor,
    requiredClientCapabilitiesForInputRequest,
    sleep,
    withRequestStateValue
} from '@modelcontextprotocol/core-internal';

/**
 * Default handler re-entries per originating request — tighter than the
 * client driver's 10 because the shim holds a live wire request open.
 */
const DEFAULT_LEGACY_SHIM_MAX_ROUNDS = 8;

/** Default per-leg timeout: legs are human-paced, so the 60s protocol default is wrong. */
const DEFAULT_LEGACY_SHIM_ROUND_TIMEOUT_MS = 600_000;

/** The `ServerOptions.inputRequired` bag with defaults applied. */
export interface ResolvedLegacyShimOptions {
    maxRounds: number;
    roundTimeoutMs: number;
    legacyShim: boolean;
}

/** Resolves and validates `ServerOptions.inputRequired`, failing loudly at construction time. */
export function resolveLegacyShimOptions(
    options: { maxRounds?: number; roundTimeoutMs?: number; legacyShim?: boolean } | undefined
): ResolvedLegacyShimOptions {
    if (options?.maxRounds !== undefined && (!Number.isInteger(options.maxRounds) || options.maxRounds < 1)) {
        throw new RangeError(`inputRequired.maxRounds must be a positive integer (got ${options.maxRounds})`);
    }
    if (options?.roundTimeoutMs !== undefined && (!Number.isFinite(options.roundTimeoutMs) || options.roundTimeoutMs <= 0)) {
        throw new RangeError(`inputRequired.roundTimeoutMs must be a positive number (got ${options.roundTimeoutMs})`);
    }
    return {
        maxRounds: options?.maxRounds ?? DEFAULT_LEGACY_SHIM_MAX_ROUNDS,
        roundTimeoutMs: options?.roundTimeoutMs ?? DEFAULT_LEGACY_SHIM_ROUND_TIMEOUT_MS,
        legacyShim: options?.legacyShim ?? true
    };
}

/** The embedded input-request kinds the 2026-07-28 revision defines. */
export type EmbeddedInputRequestMethod = 'elicitation/create' | 'sampling/createMessage' | 'roots/list';

/** A coerced `inputRequests` entry: the kind-narrowed embedded request. */
export interface CoercedEmbeddedInputRequest {
    method: EmbeddedInputRequestMethod;
    params?: Record<string, unknown>;
}

/**
 * Validates one `inputRequests` entry: malformed or unknown kinds are server
 * bugs and fail loudly on both eras. Shared by the modern seam's capability
 * check and the shim's gate.
 */
export function coerceEmbeddedInputRequest(
    method: string,
    key: string,
    entry: unknown
): { embedded: CoercedEmbeddedInputRequest; required: ClientCapabilities } {
    if (entry === null || typeof entry !== 'object' || typeof (entry as { method?: unknown }).method !== 'string') {
        throw new ProtocolError(
            ProtocolErrorCode.InternalError,
            `Handler for ${method} returned an invalid input request '${key}': each inputRequests entry must be an ` +
                `embedded elicitation/create, sampling/createMessage, or roots/list request`
        );
    }
    const embedded = entry as { method: string; params?: Record<string, unknown> };
    const required = requiredClientCapabilitiesForInputRequest(embedded);
    if (required === undefined) {
        throw new ProtocolError(
            ProtocolErrorCode.InternalError,
            `Handler for ${method} returned an input request '${key}' of kind '${embedded.method}', which is not an ` +
                `embedded request the 2026-07-28 revision defines`
        );
    }
    return { embedded: embedded as CoercedEmbeddedInputRequest, required };
}

/**
 * The 2025-11-25 URL-mode wire shape requires an `elicitationId`; the 2026
 * in-band shape has none, so URL legs mint one (CSPRNG-backed, with a
 * getRandomValues fallback for runtimes without `randomUUID`).
 */
function syntheticElicitationId(): string {
    const webCrypto = globalThis.crypto;
    if (webCrypto?.randomUUID !== undefined) {
        return webCrypto.randomUUID();
    }
    const bytes = new Uint8Array(16);
    webCrypto.getRandomValues(bytes);
    bytes[6] = (bytes[6]! & 0x0f) | 0x40;
    bytes[8] = (bytes[8]! & 0x3f) | 0x80;
    const hex = [...bytes].map(byte => byte.toString(16).padStart(2, '0')).join('');
    return `${hex.slice(0, 8)}-${hex.slice(8, 12)}-${hex.slice(12, 16)}-${hex.slice(16, 20)}-${hex.slice(20)}`;
}

/** Per-family surfacing: tools/call → isError result (the 2025 idiom); prompts/resources → JSON-RPC error. */
function legacyShimFailure(method: string, message: string): Result {
    if (method === 'tools/call') {
        return { content: [{ type: 'text', text: message }], isError: true };
    }
    throw new ProtocolError(ProtocolErrorCode.InternalError, message);
}

/**
 * Everything the shim needs from `Server`: the knobs, the per-request
 * resolved capability view (initialize state on sessionful legacy; empty on
 * per-request stateless instances), the requestState verify runner
 * (deny-on-error → the frozen `-32602`), and the 2025-era senders. The
 * shim's own gate is authoritative; elicitation accepted content passes
 * through UNVALIDATED for parity with the modern client driver.
 */
export interface LegacyInputRequiredShimHost {
    readonly maxRounds: number;
    readonly roundTimeoutMs: number;
    resolvedClientCapabilities(ctx: ServerContext): ClientCapabilities | undefined;
    verifyRequestState(state: string, ctx: ServerContext, method: string): Promise<unknown>;
    sendElicitation(params: ElicitRequestFormParams | ElicitRequestURLParams, options: RequestOptions): Promise<unknown>;
    sendSampling(params: CreateMessageRequest['params'], options: RequestOptions): Promise<unknown>;
    listRoots(params: Record<string, unknown> | undefined, options: RequestOptions): Promise<unknown>;
}

/** The fulfilment loop — see the module doc for the contract. */
export class LegacyInputRequiredShim {
    constructor(private readonly _host: LegacyInputRequiredShimHost) {}

    async fulfill(
        method: string,
        handler: (request: JSONRPCRequest, ctx: ServerContext) => Promise<Result>,
        request: JSONRPCRequest,
        ctx: ServerContext,
        firstResult: Result
    ): Promise<Result> {
        const { maxRounds, roundTimeoutMs } = this._host;
        const outerSignal = ctx.mcpReq.signal;
        let current = firstResult;
        let round = 0;

        // eslint-disable-next-line no-constant-condition
        while (true) {
            round += 1;
            if (round > maxRounds) {
                return legacyShimFailure(method, inputRequiredRoundsExceededMessage(method, maxRounds));
            }

            // At-least-one re-check per round (server bug → loud, as on modern).
            const inputRequests = current.inputRequests as Record<string, unknown> | null | undefined;
            const hasInputRequests = inputRequests != null && Object.keys(inputRequests).length > 0;
            const requestState = typeof current.requestState === 'string' ? current.requestState : undefined;
            if (!hasInputRequests && requestState === undefined) {
                throw new ProtocolError(
                    ProtocolErrorCode.InternalError,
                    `Handler for ${method} returned an input-required result with neither inputRequests nor requestState ` +
                        `(every InputRequiredResult must include at least one of the two)`
                );
            }

            let responses: Record<string, unknown> | undefined;
            if (hasInputRequests) {
                // The shim's own capability pre-check (never gated on
                // enforceStrictCapabilities). The whole round gates before
                // any wire traffic, so a refusal has no side effects.
                const declared = this._host.resolvedClientCapabilities(ctx);
                const coerced: [string, CoercedEmbeddedInputRequest][] = [];
                for (const [key, entry] of Object.entries(inputRequests!)) {
                    const { embedded, required } = coerceEmbeddedInputRequest(method, key, entry);
                    // Request-carrying kinds need params; absent = server bug.
                    if (embedded.method !== 'roots/list' && embedded.params === undefined) {
                        throw new ProtocolError(
                            ProtocolErrorCode.InternalError,
                            `Handler for ${method} returned an input request '${key}' of kind '${embedded.method}' without params`
                        );
                    }
                    const missing = missingClientCapabilities(required, declared);
                    if (missing !== undefined) {
                        return legacyShimFailure(
                            method,
                            `Cannot request input '${key}' (${embedded.method}): the client on this 2025-era connection did not ` +
                                `declare the required capability${declared === undefined ? ' (no client capabilities are available on this connection — per-request legacy serving cannot receive server-to-client requests)' : ''}`
                        );
                    }
                    coerced.push([key, embedded]);
                }

                // Fulfil concurrently (driver parity); first failure aborts siblings.
                const roundAbort = linkedRoundAbort(outerSignal);
                try {
                    const legOptions: RequestOptions = {
                        relatedRequestId: ctx.mcpReq.id,
                        timeout: roundTimeoutMs,
                        resetTimeoutOnProgress: true,
                        // The no-op handler stamps a progressToken on the leg —
                        // without one, resetTimeoutOnProgress could never fire.
                        onprogress: () => {},
                        signal: roundAbort.signal
                    };
                    const fulfilled = await Promise.all(
                        coerced.map(async ([key, embedded]) => {
                            try {
                                return [key, await this._dispatchLeg(embedded, legOptions)] as const;
                            } catch (error) {
                                roundAbort.abort(error);
                                throw error;
                            }
                        })
                    );
                    responses = Object.fromEntries(fulfilled);
                } catch (error) {
                    if (outerSignal.aborted) {
                        // Cancelled requests are never answered — propagate.
                        throw error;
                    }
                    return legacyShimFailure(
                        method,
                        `Fulfilling input required by '${method}' failed: ${error instanceof Error ? error.message : String(error)}`
                    );
                } finally {
                    roundAbort.dispose();
                }
            } else {
                // requestState-only round: paced so the loop never hot-spins
                // (driver parity); counted in the same round cap.
                await sleep(REQUEST_STATE_ONLY_LEG_PACING_MS, outerSignal);
            }

            // Byte-exact requestState echo: build the round's context first,
            // verify against it (the order and view a modern wire retry
            // gets), then swap in the decoded payload. Deny-on-error → -32602.
            let ctxNext: ServerContext = {
                ...ctx,
                mcpReq: {
                    ...ctx.mcpReq,
                    // REPLACE semantics: this round's responses only — multi-step
                    // flows thread earlier answers through requestState.
                    inputResponses: responses,
                    droppedInputResponseKeys: undefined,
                    requestState: requestStateAccessor(requestState)
                }
            };
            if (requestState !== undefined) {
                const decoded = await this._host.verifyRequestState(requestState, ctxNext, method);
                if (decoded !== undefined) {
                    ctxNext = withRequestStateValue(ctxNext, decoded);
                }
            }

            // Re-entry hits the same stored handler a wire retry would
            // (for McpServer: the full funnel).
            const next = await handler(request, ctxNext);
            if (!isInputRequiredResult(next)) {
                return next;
            }
            current = next;
        }
    }

    /** Routes one embedded request through the host's existing 2025-era senders (gate already ran). */
    private async _dispatchLeg(embedded: CoercedEmbeddedInputRequest, options: RequestOptions): Promise<unknown> {
        switch (embedded.method) {
            case 'elicitation/create': {
                let params = embedded.params as ElicitRequestFormParams | ElicitRequestURLParams;
                if (params.mode === 'url' && (params as ElicitRequestURLParams).elicitationId === undefined) {
                    params = { ...(params as ElicitRequestURLParams), elicitationId: syntheticElicitationId() };
                }
                return await this._host.sendElicitation(params, options);
            }
            case 'sampling/createMessage': {
                return await this._host.sendSampling(embedded.params as CreateMessageRequest['params'], options);
            }
            case 'roots/list': {
                return await this._host.listRoots(embedded.params, options);
            }
        }
    }
}
